OPOSICIONES.push({"id": "abanto-administrativo", "nombre": "Administrativo/a · Ayuntamiento de Abanto Zierbena", "sub": "5 plazas, C1. BOB nº 91, 18/05/2026. 40 temas.", "temas": [{"id": "t01", "sig": "Tema 1", "titulo": "Tema 1. La Constitución Española de 1978 (I): Título Preliminar (arts. 1–9)", "sub": "Parte Primera", "preguntas": [], "incluye": ["biblioteca-dfb/t01:1-10+31-32"]}, {"id": "t02", "sig": "Tema 2", "titulo": "Tema 2. La Constitución Española de 1978 (II): derechos y deberes fundamentales (arts. 10–30)", "sub": "Parte Primera", "preguntas": [], "incluye": ["biblioteca-dfb/t01:11-24+33-34", "getxo-kirolak-auxiliar/t01:1-26"]}, {"id": "t03", "sig": "Tema 3", "titulo": "Tema 3. La Constitución Española de 1978 (III): las Cortes Generales (Título III, Caps. I–III)", "sub": "Parte Primera", "preguntas": [{"id": "abat03q01", "q": "Según el art. 66 de la Constitución, las Cortes Generales están formadas por:", "o": ["El Congreso de los Diputados y el Senado", "El Congreso, el Senado y el Gobierno", "El Congreso y los Parlamentos autonómicos", "El Senado y el Consejo de Estado"], "e": "Representan al pueblo español, ejercen la potestad legislativa, aprueban los Presupuestos y controlan la acción del Gobierno.", "r": "CE art. 66"}, {"id": "abat03q02", "q": "Las Cortes Generales, según el art. 66.3, son:", "o": ["Inviolables", "Irresponsables", "Inamovibles", "Independientes"], "e": "Es la cita literal del art. 66.3.", "r": "CE art. 66.3"}, {"id": "abat03q03", "q": "¿Puede una persona ser a la vez diputada en el Congreso y miembro de un Parlamento autonómico?", "o": ["No, no se puede acumular el acta de una Asamblea autonómica con la de diputado al Congreso", "Sí, sin limitación", "Sí, si renuncia al sueldo autonómico", "Solo si es de una Comunidad uniprovincial"], "e": "Tampoco se puede ser miembro de las dos Cámaras simultáneamente.", "r": "CE art. 67.1"}, {"id": "abat03q04", "q": "Los miembros de las Cortes Generales:", "o": ["No están ligados por mandato imperativo", "Deben votar siempre lo que diga su partido", "Responden ante sus electores mediante revocación", "Representan solo a su provincia"], "e": "Art. 67.2.", "r": "CE art. 67.2"}, {"id": "abat03q05", "q": "¿Cuántos diputados tiene como mínimo y como máximo el Congreso según la Constitución?", "o": ["Mínimo 300 y máximo 400", "Mínimo 350 y máximo 400", "Mínimo 250 y máximo 350", "Exactamente 350"], "e": "La Constitución da el margen; la ley electoral fija 350.", "r": "CE art. 68.1"}, {"id": "abat03q06", "q": "En las elecciones al Congreso, la circunscripción electoral es:", "o": ["La provincia", "La Comunidad Autónoma", "El municipio", "Todo el territorio nacional"], "e": "Ceuta y Melilla están representadas cada una por un diputado.", "r": "CE art. 68.2"}, {"id": "abat03q07", "q": "El sistema electoral del Congreso, según la Constitución, atiende a criterios de:", "o": ["Representación proporcional", "Representación mayoritaria", "Representación paritaria por provincias", "Representación territorial de las Comunidades"], "e": "Art. 68.3.", "r": "CE art. 68.3"}, {"id": "abat03q08", "q": "Las elecciones generales tienen lugar entre:", "o": ["Los 30 y 60 días desde la terminación del mandato", "Los 15 y 30 días", "Los 45 y 90 días", "Los 60 y 90 días"], "e": "El Congreso electo debe ser convocado dentro de los 25 días siguientes a la celebración de las elecciones.", "r": "CE art. 68.6"}, {"id": "abat03q09", "q": "¿Cuántos senadores elige cada provincia peninsular?", "o": ["Cuatro", "Tres", "Dos", "Uno por cada millón de habitantes"], "e": "Las islas mayores eligen tres; Ceuta y Melilla, dos cada una.", "r": "CE art. 69.2"}, {"id": "abat03q10", "q": "Las Comunidades Autónomas designan senadores:", "o": ["Uno, y otro más por cada millón de habitantes de su territorio", "Dos por Comunidad en todo caso", "Uno por cada provincia", "Ninguno; todos se eligen por sufragio directo"], "e": "La designación corresponde a la Asamblea legislativa o al órgano colegiado superior de la Comunidad.", "r": "CE art. 69.5"}, {"id": "abat03q11", "q": "El Senado es, según la Constitución:", "o": ["La Cámara de representación territorial", "La Cámara de representación popular", "La Cámara de control del Gobierno", "La Cámara de segunda lectura sin poder legislativo"], "e": "Art. 69.1.", "r": "CE art. 69.1"}, {"id": "abat03q12", "q": "La inmunidad parlamentaria significa que diputados y senadores:", "o": ["Solo pueden ser detenidos en caso de flagrante delito y no pueden ser inculpados ni procesados sin autorización previa de su Cámara", "No responden por las opiniones manifestadas en el ejercicio de sus funciones", "Solo pueden ser juzgados por el Tribunal Constitucional", "No pueden ser detenidos en ningún caso"], "e": "La inviolabilidad es la irresponsabilidad por sus opiniones. En las causas contra ellos es competente la Sala de lo Penal del Tribunal Supremo.", "r": "CE art. 71"}, {"id": "abat03q13", "q": "Los Reglamentos de las Cámaras se aprueban por:", "o": ["Mayoría absoluta, en una votación final sobre su totalidad", "Mayoría simple", "Mayoría de tres quintos", "Mayoría de dos tercios"], "e": "Las Cámaras también aprueban sus presupuestos y, de común acuerdo, el Estatuto del Personal de las Cortes.", "r": "CE art. 72.1"}, {"id": "abat03q14", "q": "Las sesiones conjuntas de ambas Cámaras las preside:", "o": ["El Presidente del Congreso", "El Presidente del Senado", "El Rey", "El de mayor edad de los dos Presidentes"], "e": "Se rigen por un Reglamento de las Cortes Generales aprobado por mayoría absoluta de cada Cámara.", "r": "CE art. 72.2"}, {"id": "abat03q15", "q": "¿Cuáles son los períodos ordinarios de sesiones de las Cámaras?", "o": ["De septiembre a diciembre y de febrero a junio", "De enero a junio y de septiembre a diciembre", "De octubre a junio", "Todo el año salvo agosto"], "e": "Art. 73.1.", "r": "CE art. 73.1"}, {"id": "abat03q16", "q": "¿Quién puede pedir que las Cámaras se reúnan en sesión extraordinaria?", "o": ["El Gobierno, la Diputación Permanente o la mayoría absoluta de los miembros de cualquiera de las Cámaras", "Solo el Rey", "El Presidente del Gobierno y el Defensor del Pueblo", "Un tercio de los diputados"], "e": "Se convocan con un orden del día determinado y se clausuran una vez agotado.", "r": "CE art. 73.2"}, {"id": "abat03q17", "q": "¿Cuál de estas materias NO puede delegarse en las Comisiones Legislativas Permanentes?", "o": ["Los Presupuestos Generales del Estado", "Una ley ordinaria sobre carreteras", "Una ley ordinaria sobre medio ambiente", "Una ley de modificación del Código Civil"], "e": "Tampoco la reforma constitucional, las cuestiones internacionales y las leyes orgánicas y de bases.", "r": "CE art. 75.3"}, {"id": "abat03q18", "q": "Las conclusiones de las comisiones de investigación:", "o": ["No son vinculantes para los Tribunales ni afectan a las resoluciones judiciales", "Vinculan a los Tribunales", "Tienen fuerza de sentencia", "Solo pueden comunicarse al Gobierno"], "e": "El resultado puede comunicarse al Ministerio Fiscal. Comparecer a requerimiento de las Cámaras es obligatorio.", "r": "CE art. 76"}, {"id": "abat03q19", "q": "¿Cuántos miembros tiene como mínimo cada Diputación Permanente?", "o": ["Veintiuno", "Quince", "Treinta", "Diez"], "e": "La preside el Presidente de la Cámara respectiva.", "r": "CE art. 78.1"}, {"id": "abat03q20", "q": "Para que las Cámaras adopten acuerdos válidos, deben estar reunidas:", "o": ["Reglamentariamente y con asistencia de la mayoría de sus miembros", "Con la asistencia de un tercio de sus miembros", "Con la totalidad de sus miembros", "Con la asistencia del Gobierno"], "e": "Los acuerdos se adoptan por mayoría de los presentes, salvo mayorías especiales. El voto es personal e indelegable.", "r": "CE art. 79"}, {"id": "abat03q21", "q": "¿Cuántas firmas acreditadas exige la iniciativa legislativa popular?", "o": ["No menos de 500.000", "100.000", "250.000", "1.000.000"], "e": "No cabe en materias de ley orgánica, tributarias, de carácter internacional ni en la prerrogativa de gracia.", "r": "CE art. 87.3"}, {"id": "abat03q22", "q": "Los proyectos de ley se aprueban en:", "o": ["El Consejo de Ministros, que los somete al Congreso", "El Congreso, que los remite al Gobierno", "La Comisión General de Codificación", "El Senado"], "e": "Van acompañados de exposición de motivos y de los antecedentes necesarios.", "r": "CE art. 88"}, {"id": "abat03q23", "q": "¿De qué plazo dispone el Senado para oponer su veto o introducir enmiendas a un proyecto de ley ordinario?", "o": ["Dos meses desde la recepción del texto", "Un mes", "Veinte días naturales", "Tres meses"], "e": "En los proyectos declarados urgentes, el plazo es de veinte días naturales.", "r": "CE art. 90"}, {"id": "abat03q24", "q": "El veto del Senado debe aprobarse por:", "o": ["Mayoría absoluta", "Mayoría simple", "Mayoría de tres quintos", "Mayoría de dos tercios"], "e": "El Congreso puede levantarlo por mayoría absoluta o, pasados dos meses, por mayoría simple.", "r": "CE art. 90.2"}, {"id": "abat03q25", "q": "¿En qué plazo sanciona el Rey las leyes aprobadas por las Cortes?", "o": ["Quince días", "Treinta días", "Diez días", "Un mes"], "e": "Las sanciona, las promulga y ordena su inmediata publicación.", "r": "CE art. 91"}, {"id": "abat03q26", "q": "El referéndum consultivo sobre decisiones políticas de especial trascendencia lo convoca:", "o": ["El Rey, a propuesta del Presidente del Gobierno, previamente autorizada por el Congreso", "El Presidente del Gobierno directamente", "El Congreso por mayoría absoluta", "El Rey, a propuesta del Senado"], "e": "Una ley orgánica regula sus modalidades.", "r": "CE art. 92"}, {"id": "abat03q27", "q": "La celebración de tratados que atribuyan a una organización internacional el ejercicio de competencias derivadas de la Constitución se autoriza mediante:", "o": ["Ley orgánica", "Ley ordinaria", "Mayoría simple de las Cortes", "Real Decreto"], "e": "Es la vía por la que España entró en las Comunidades Europeas.", "r": "CE art. 93"}, {"id": "abat03q28", "q": "Un tratado internacional con estipulaciones contrarias a la Constitución exige:", "o": ["La previa revisión constitucional", "Su aprobación por mayoría de tres quintos", "Un referéndum", "Un dictamen del Consejo de Estado"], "e": "El Gobierno o cualquiera de las Cámaras puede pedir al Tribunal Constitucional que declare si existe esa contradicción.", "r": "CE art. 95"}]}, {"id": "t04", "sig": "Tema 4", "titulo": "Tema 4. La Constitución Española de 1978 (IV): relaciones entre el Gobierno y las Cortes Generales (Título V)", "sub": "Parte Primera", "preguntas": [{"id": "abat04q01", "q": "Según el art. 108 de la Constitución, el Gobierno responde solidariamente en su gestión política ante:", "o": ["El Congreso de los Diputados", "Las Cortes Generales", "El Senado", "El Rey"], "e": "No responde ante el Senado.", "r": "CE art. 108"}, {"id": "abat04q02", "q": "Las Cámaras pueden recabar información y ayuda del Gobierno y de cualesquiera autoridades del Estado y de las Comunidades Autónomas a través de:", "o": ["Sus Presidentes", "El Defensor del Pueblo", "El Tribunal de Cuentas", "La Diputación Permanente"], "e": "Art. 109.", "r": "CE art. 109"}, {"id": "abat04q03", "q": "Los miembros del Gobierno, respecto de las sesiones de las Cámaras:", "o": ["Tienen acceso a ellas y la facultad de hacerse oír", "No pueden asistir salvo que sean parlamentarios", "Pueden votar aunque no sean parlamentarios", "Solo pueden asistir a las sesiones de Comisión"], "e": "Pueden pedir que informen ante ellas funcionarios de sus Departamentos.", "r": "CE art. 110.2"}, {"id": "abat04q04", "q": "Toda interpelación puede dar lugar a:", "o": ["Una moción en la que la Cámara manifieste su posición", "Una moción de censura automática", "Una cuestión de confianza", "La disolución de las Cámaras"], "e": "El Gobierno y cada uno de sus miembros están sometidos a interpelaciones y preguntas; los Reglamentos fijan un tiempo mínimo semanal.", "r": "CE art. 111"}, {"id": "abat04q05", "q": "¿Quién puede plantear la cuestión de confianza?", "o": ["El Presidente del Gobierno, previa deliberación del Consejo de Ministros", "Una décima parte de los diputados", "El Rey", "Cualquier ministro"], "e": "Puede plantearla sobre su programa o sobre una declaración de política general.", "r": "CE art. 112"}, {"id": "abat04q06", "q": "La confianza se entiende otorgada cuando vota a favor:", "o": ["La mayoría simple de los diputados", "La mayoría absoluta del Congreso", "Tres quintos del Congreso", "La mayoría absoluta de cada Cámara"], "e": "Si el Congreso niega la confianza, el Gobierno presenta su dimisión al Rey.", "r": "CE arts. 112 y 114.1"}, {"id": "abat04q07", "q": "La moción de censura debe ser propuesta al menos por:", "o": ["La décima parte de los diputados", "La quinta parte de los diputados", "Cincuenta diputados", "Un grupo parlamentario"], "e": "Y debe incluir un candidato a la Presidencia del Gobierno.", "r": "CE art. 113.2"}, {"id": "abat04q08", "q": "La moción de censura se aprueba por:", "o": ["Mayoría absoluta del Congreso", "Mayoría simple del Congreso", "Mayoría absoluta de las Cortes Generales", "Mayoría de tres quintos"], "e": "Art. 113.1.", "r": "CE art. 113.1"}, {"id": "abat04q09", "q": "La moción de censura no puede votarse hasta que transcurran:", "o": ["Cinco días desde su presentación", "Dos días desde su presentación", "Diez días desde su presentación", "Un mes desde su presentación"], "e": "En los dos primeros días pueden presentarse mociones alternativas.", "r": "CE art. 113.3"}, {"id": "abat04q10", "q": "Si la moción de censura no es aprobada, sus signatarios:", "o": ["No pueden presentar otra durante el mismo período de sesiones", "No pueden presentar otra en la misma legislatura", "Deben abandonar su escaño", "No tienen ninguna limitación"], "e": "Art. 113.4.", "r": "CE art. 113.4"}, {"id": "abat04q11", "q": "Si el Congreso aprueba una moción de censura:", "o": ["El Gobierno presenta su dimisión y el candidato incluido en la moción se entiende investido de la confianza", "Se convocan elecciones automáticamente", "El Rey propone un nuevo candidato", "El Senado debe ratificarla"], "e": "El Rey lo nombra Presidente del Gobierno.", "r": "CE art. 114.2"}, {"id": "abat04q12", "q": "¿Quién decreta la disolución del Congreso, del Senado o de las Cortes Generales?", "o": ["El Rey, a propuesta del Presidente del Gobierno, previa deliberación del Consejo de Ministros", "El Presidente del Gobierno directamente", "El Presidente del Congreso", "El Consejo de Ministros"], "e": "El decreto de disolución fija la fecha de las elecciones.", "r": "CE art. 115.1"}, {"id": "abat04q13", "q": "La propuesta de disolución NO puede presentarse:", "o": ["Mientras esté en trámite una moción de censura", "Durante el primer año de legislatura en ningún caso", "Fuera del período de sesiones", "Durante el estado de alarma, si hay acuerdo del Senado"], "e": "Tampoco cabe nueva disolución antes de que transcurra un año desde la anterior, salvo la del art. 99.5.", "r": "CE art. 115.2 y 3"}, {"id": "abat04q14", "q": "El estado de alarma lo declara:", "o": ["El Gobierno, mediante decreto acordado en Consejo de Ministros, por un plazo máximo de quince días", "El Congreso por mayoría absoluta", "El Gobierno, previa autorización del Congreso, por treinta días", "El Rey"], "e": "Se da cuenta al Congreso, sin cuya autorización no puede prorrogarse.", "r": "CE art. 116.2"}, {"id": "abat04q15", "q": "El estado de excepción lo declara:", "o": ["El Gobierno, previa autorización del Congreso, por un plazo máximo de treinta días prorrogable por otros treinta", "El Congreso por mayoría absoluta, a propuesta del Gobierno", "El Gobierno sin autorización, por quince días", "El Senado por mayoría absoluta"], "e": "Art. 116.3.", "r": "CE art. 116.3"}, {"id": "abat04q16", "q": "El estado de sitio lo declara:", "o": ["El Congreso por mayoría absoluta, a propuesta exclusiva del Gobierno", "El Gobierno, dando cuenta al Congreso", "El Rey, a propuesta del Jefe del Estado Mayor", "El Senado por mayoría absoluta"], "e": "El Congreso determina su ámbito territorial, duración y condiciones.", "r": "CE art. 116.4"}, {"id": "abat04q17", "q": "Mientras esté declarado alguno de los estados del art. 116:", "o": ["No puede procederse a la disolución del Congreso", "Se suspende el funcionamiento de las Cámaras", "El Gobierno puede legislar sin control", "Se suspenden todas las elecciones municipales"], "e": "Las Cámaras quedan convocadas automáticamente si no están en período de sesiones.", "r": "CE art. 116.5"}, {"id": "abat04q18", "q": "Si el Congreso está disuelto o ha expirado su mandato cuando se declara un estado de alarma, excepción o sitio, sus competencias las asume:", "o": ["Su Diputación Permanente", "El Senado", "El Gobierno", "El Tribunal Constitucional"], "e": "Art. 116.5.", "r": "CE art. 116.5"}, {"id": "abat04q19", "q": "¿Qué ley orgánica regula los estados de alarma, excepción y sitio?", "o": ["La LO 4/1981", "La LO 6/1985", "La LO 2/1979", "La LO 3/1979"], "e": "La LO 6/1985 es la del Poder Judicial; la 2/1979, la del Tribunal Constitucional.", "r": "LO 4/1981"}, {"id": "abat04q20", "q": "¿Qué artículos forman el Título V de la Constitución?", "o": ["Los arts. 108 a 116", "Los arts. 97 a 107", "Los arts. 117 a 127", "Los arts. 66 a 96"], "e": "El Título IV (arts. 97-107) regula el Gobierno y la Administración.", "r": "CE, estructura"}, {"id": "abat04q21", "q": "La declaración de los estados de alarma, excepción o sitio:", "o": ["No modifica el principio de responsabilidad del Gobierno y de sus agentes", "Suspende la responsabilidad del Gobierno", "Suspende todos los derechos fundamentales", "Atribuye al Rey el mando de las Fuerzas Armadas y del Gobierno"], "e": "Art. 116.6.", "r": "CE art. 116.6"}, {"id": "abat04q22", "q": "Cuando la disolución se produce automáticamente por no haberse investido Presidente en dos meses, se aplica:", "o": ["El art. 99.5", "El art. 115.3", "El art. 113.4", "El art. 116.5"], "e": "Es la excepción a la regla de que no cabe nueva disolución antes de un año.", "r": "CE art. 99.5"}]}, {"id": "t05", "sig": "Tema 5", "titulo": "Tema 5. La Constitución Española de 1978 (V): el Poder Judicial (Título VI)", "sub": "Parte Primera", "preguntas": [{"id": "abat05q01", "q": "Según el art. 117.1 de la Constitución, la justicia emana:", "o": ["Del pueblo y se administra en nombre del Rey", "Del Rey y se administra en nombre del pueblo", "Del Estado y se administra en nombre de la ley", "De las Cortes y se administra en nombre del Rey"], "e": "Por Jueces y Magistrados independientes, inamovibles, responsables y sometidos únicamente al imperio de la ley.", "r": "CE art. 117.1"}, {"id": "abat05q02", "q": "¿Cuál de estas características NO atribuye el art. 117.1 a los Jueces y Magistrados?", "o": ["Elegibles", "Independientes", "Inamovibles", "Responsables"], "e": "Además, están sometidos únicamente al imperio de la ley.", "r": "CE art. 117.1"}, {"id": "abat05q03", "q": "El ejercicio de la potestad jurisdiccional, juzgando y haciendo ejecutar lo juzgado, corresponde:", "o": ["Exclusivamente a los Juzgados y Tribunales determinados por las leyes", "A los Juzgados, Tribunales y al Ministerio Fiscal", "Al Consejo General del Poder Judicial", "A los Tribunales y al Gobierno en ciertos casos"], "e": "Es el principio de exclusividad (art. 117.3).", "r": "CE art. 117.3"}, {"id": "abat05q04", "q": "El principio de unidad jurisdiccional es:", "o": ["La base de la organización y funcionamiento de los Tribunales", "La prohibición de la jurisdicción militar", "La existencia de un único juez por provincia", "La sumisión de todos los jueces al Tribunal Constitucional"], "e": "La ley regula la jurisdicción militar en el ámbito castrense y en los supuestos de estado de sitio.", "r": "CE art. 117.5"}, {"id": "abat05q05", "q": "Según el art. 117.6 de la Constitución:", "o": ["Se prohíben los Tribunales de excepción", "Se permiten los Tribunales de excepción en estado de sitio", "Se crean los Tribunales de Honor", "Se suprime la jurisdicción militar"], "e": "Art. 117.6.", "r": "CE art. 117.6"}, {"id": "abat05q06", "q": "La justicia es gratuita:", "o": ["Cuando así lo disponga la ley y, en todo caso, para quienes acrediten insuficiencia de recursos para litigar", "Siempre, para cualquier persona", "Nunca", "Solo en el orden penal"], "e": "Art. 119.", "r": "CE art. 119"}, {"id": "abat05q07", "q": "Según el art. 120, las sentencias:", "o": ["Serán siempre motivadas y se pronunciarán en audiencia pública", "Pueden no ser motivadas en el orden civil", "Se pronuncian siempre a puerta cerrada", "Solo son públicas en el orden penal"], "e": "El procedimiento será predominantemente oral, sobre todo en materia criminal.", "r": "CE art. 120"}, {"id": "abat05q08", "q": "Los daños causados por error judicial y los que sean consecuencia del funcionamiento anormal de la Administración de Justicia dan derecho a una indemnización a cargo de:", "o": ["El Estado", "El juez responsable", "La Comunidad Autónoma", "El Consejo General del Poder Judicial"], "e": "Conforme a la ley.", "r": "CE art. 121"}, {"id": "abat05q09", "q": "El órgano de gobierno del Poder Judicial es:", "o": ["El Consejo General del Poder Judicial", "El Tribunal Supremo", "El Ministerio de Justicia", "El Tribunal Constitucional"], "e": "Art. 122.2.", "r": "CE art. 122.2"}, {"id": "abat05q10", "q": "¿Cuántos miembros forman el Consejo General del Poder Judicial, además de su Presidente?", "o": ["Veinte, nombrados por el Rey por un período de cinco años", "Doce, nombrados por cuatro años", "Veinte, nombrados por nueve años", "Quince, nombrados por cinco años"], "e": "El Presidente es el del Tribunal Supremo.", "r": "CE art. 122.3"}, {"id": "abat05q11", "q": "De los veinte vocales del CGPJ, ¿cuántos se eligen entre Jueces y Magistrados de todas las categorías judiciales?", "o": ["Doce", "Ocho", "Diez", "Veinte"], "e": "Los otros ocho los proponen el Congreso (cuatro) y el Senado (cuatro), por mayoría de tres quintos.", "r": "CE art. 122.3"}, {"id": "abat05q12", "q": "Los vocales del CGPJ propuestos por las Cámaras deben ser abogados y otros juristas de reconocida competencia con más de:", "o": ["Quince años de ejercicio en su profesión", "Diez años", "Veinte años", "Cinco años"], "e": "Los proponen el Congreso y el Senado, cuatro cada uno, por mayoría de tres quintos.", "r": "CE art. 122.3"}, {"id": "abat05q13", "q": "El Tribunal Supremo es el órgano jurisdiccional superior en todos los órdenes, salvo en materia de:", "o": ["Garantías constitucionales", "Derecho penal", "Derecho militar", "Derecho foral"], "e": "Las garantías constitucionales corresponden al Tribunal Constitucional.", "r": "CE art. 123.1"}, {"id": "abat05q14", "q": "El Presidente del Tribunal Supremo es nombrado por el Rey a propuesta de:", "o": ["El Consejo General del Poder Judicial", "El Gobierno", "El Congreso de los Diputados", "El propio Tribunal Supremo"], "e": "En la forma que determine la ley.", "r": "CE art. 123.2"}, {"id": "abat05q15", "q": "¿Cuál de estos principios rige la actuación del Ministerio Fiscal?", "o": ["Unidad de actuación y dependencia jerárquica, con sujeción a los de legalidad e imparcialidad", "Independencia y libre designación", "Inamovilidad y autonomía", "Oportunidad y discrecionalidad"], "e": "Ejerce sus funciones por medio de órganos propios.", "r": "CE art. 124.2"}, {"id": "abat05q16", "q": "El Fiscal General del Estado es nombrado por el Rey:", "o": ["A propuesta del Gobierno, oído el Consejo General del Poder Judicial", "A propuesta del Consejo General del Poder Judicial", "A propuesta del Congreso por mayoría de tres quintos", "A propuesta del Tribunal Supremo"], "e": "Art. 124.4.", "r": "CE art. 124.4"}, {"id": "abat05q17", "q": "¿Cuál es la misión del Ministerio Fiscal según el art. 124?", "o": ["Promover la acción de la justicia en defensa de la legalidad, de los derechos de los ciudadanos y del interés público tutelado por la ley", "Juzgar los delitos más graves", "Gobernar el Poder Judicial", "Defender al Estado en todos los juicios"], "e": "También velar por la independencia de los Tribunales y procurar ante ellos la satisfacción del interés social.", "r": "CE art. 124.1"}, {"id": "abat05q18", "q": "¿Cuál de estas formas de participación ciudadana en la Administración de Justicia recoge el art. 125?", "o": ["La acción popular y la institución del Jurado", "La elección de los jueces por sufragio", "La designación de los fiscales por los Ayuntamientos", "La revisión de sentencias por referéndum"], "e": "También los Tribunales consuetudinarios y tradicionales.", "r": "CE art. 125"}, {"id": "abat05q19", "q": "La policía judicial depende de:", "o": ["Los Jueces, los Tribunales y el Ministerio Fiscal, en sus funciones de averiguación del delito", "El Ministerio del Interior exclusivamente", "El Consejo General del Poder Judicial", "Los Ayuntamientos"], "e": "Art. 126.", "r": "CE art. 126"}, {"id": "abat05q20", "q": "Los Jueces, Magistrados y Fiscales en activo:", "o": ["No pueden desempeñar otros cargos públicos ni pertenecer a partidos políticos o sindicatos", "Pueden pertenecer a partidos políticos, pero no a sindicatos", "Pueden afiliarse libremente a partidos y sindicatos", "No pueden formar asociaciones profesionales"], "e": "Sí pueden asociarse profesionalmente.", "r": "CE art. 127.1"}, {"id": "abat05q21", "q": "¿Qué ley orgánica desarrolla el Título VI de la Constitución?", "o": ["La LO 6/1985, del Poder Judicial", "La LO 2/1979, del Tribunal Constitucional", "La LO 4/1981", "La LO 50/1981"], "e": "Determina la constitución, funcionamiento y gobierno de los Juzgados y Tribunales y el estatuto de los Jueces.", "r": "CE art. 122.1"}, {"id": "abat05q22", "q": "¿Qué artículos forman el Título VI de la Constitución?", "o": ["Los arts. 117 a 127", "Los arts. 108 a 116", "Los arts. 128 a 136", "Los arts. 159 a 165"], "e": "El Título VI se titula «Del Poder Judicial».", "r": "CE, estructura"}]}, {"id": "t06", "sig": "Tema 6", "titulo": "Tema 6. La Constitución Española de 1978 (VI): organización territorial del Estado (Título VIII)", "sub": "Parte Primera", "preguntas": [], "incluye": ["getxo-administrativo/t02", "getxo-kirolak-auxiliar/t02"]}, {"id": "t07", "sig": "Tema 7", "titulo": "Tema 7. La Constitución Española de 1978 (VII): el Tribunal Constitucional (Título IX) y la reforma constitucional (Título X)", "sub": "Parte Primera", "preguntas": [{"id": "abat07q01", "q": "¿Cuántos miembros tiene el Tribunal Constitucional?", "o": ["Doce, nombrados por el Rey", "Nueve, nombrados por el Rey", "Quince, nombrados por las Cortes", "Doce, nombrados por el Consejo General del Poder Judicial"], "e": "Art. 159.1.", "r": "CE art. 159.1"}, {"id": "abat07q02", "q": "¿Cómo se reparten las propuestas de los doce magistrados del Tribunal Constitucional?", "o": ["Cuatro el Congreso, cuatro el Senado, dos el Gobierno y dos el Consejo General del Poder Judicial", "Seis el Congreso y seis el Senado", "Cuatro el Congreso, cuatro el Senado y cuatro el Gobierno", "Tres cada uno: Congreso, Senado, Gobierno y CGPJ"], "e": "Los del Congreso y el Senado, por mayoría de tres quintos de sus miembros.", "r": "CE art. 159.1"}, {"id": "abat07q03", "q": "Los magistrados del Tribunal Constitucional se designan por un período de:", "o": ["Nueve años, renovándose por terceras partes cada tres", "Doce años, renovándose por mitades cada seis", "Cinco años, renovándose en bloque", "Seis años, renovándose por terceras partes cada dos"], "e": "Art. 159.3.", "r": "CE art. 159.3"}, {"id": "abat07q04", "q": "Los miembros del Tribunal Constitucional deben ser juristas de reconocida competencia con más de:", "o": ["Quince años de ejercicio profesional", "Diez años de ejercicio profesional", "Veinte años de ejercicio profesional", "Cinco años de ejercicio profesional"], "e": "Magistrados, fiscales, profesores de universidad, funcionarios públicos y abogados.", "r": "CE art. 159.2"}, {"id": "abat07q05", "q": "El Presidente del Tribunal Constitucional es nombrado por el Rey:", "o": ["Entre sus miembros, a propuesta del mismo Tribunal en pleno, por un período de tres años", "A propuesta del Gobierno, por nueve años", "A propuesta del Congreso, por cuatro años", "A propuesta del CGPJ, por cinco años"], "e": "Art. 160.", "r": "CE art. 160"}, {"id": "abat07q06", "q": "¿Cuál de estos cargos es compatible con la condición de miembro del Tribunal Constitucional?", "o": ["Ninguno de los citados: todos son incompatibles", "Diputado o senador", "Miembro de la dirección de un partido político", "Juez en activo"], "e": "También es incompatible con cualquier actividad profesional o mercantil.", "r": "CE art. 159.4"}, {"id": "abat07q07", "q": "¿Cuál de estas NO es una competencia del Tribunal Constitucional según el art. 161?", "o": ["Resolver los recursos de casación en el orden civil", "El recurso de inconstitucionalidad contra leyes y disposiciones normativas con fuerza de ley", "El recurso de amparo por violación de los derechos del art. 53.2", "Los conflictos de competencia entre el Estado y las Comunidades Autónomas"], "e": "La casación corresponde al Tribunal Supremo.", "r": "CE art. 161.1"}, {"id": "abat07q08", "q": "Cuando el Gobierno impugna ante el Tribunal Constitucional una disposición de una Comunidad Autónoma:", "o": ["La disposición queda suspendida, y el Tribunal debe ratificar o levantar la suspensión en un plazo no superior a cinco meses", "No se produce ninguna suspensión", "La disposición queda anulada definitivamente", "La suspensión dura un año como mínimo"], "e": "Art. 161.2.", "r": "CE art. 161.2"}, {"id": "abat07q09", "q": "¿Quién está legitimado para interponer el recurso de inconstitucionalidad?", "o": ["El Presidente del Gobierno, el Defensor del Pueblo, 50 diputados, 50 senadores y los órganos colegiados ejecutivos y asambleas de las Comunidades Autónomas", "Cualquier persona con interés legítimo", "El Ministerio Fiscal y el Defensor del Pueblo", "Los jueces y tribunales"], "e": "En su caso, los órganos de las Comunidades Autónomas.", "r": "CE art. 162.1.a"}, {"id": "abat07q10", "q": "¿Quién puede interponer el recurso de amparo?", "o": ["Toda persona natural o jurídica que invoque un interés legítimo, el Defensor del Pueblo y el Ministerio Fiscal", "Solo el Defensor del Pueblo", "50 diputados o 50 senadores", "El Presidente del Gobierno"], "e": "El Defensor del Pueblo puede interponer los dos recursos; el Ministerio Fiscal, solo el amparo.", "r": "CE art. 162.1.b"}, {"id": "abat07q11", "q": "La cuestión de inconstitucionalidad la plantea:", "o": ["Un órgano judicial que considere que una norma con rango de ley aplicable al caso, de cuya validez dependa el fallo, puede ser contraria a la Constitución", "El Gobierno contra una ley autonómica", "Cualquier ciudadano ante el Tribunal Constitucional", "El Defensor del Pueblo"], "e": "En ningún caso tiene efectos suspensivos.", "r": "CE art. 163"}, {"id": "abat07q12", "q": "Las sentencias del Tribunal Constitucional:", "o": ["Tienen valor de cosa juzgada a partir del día siguiente de su publicación y no cabe recurso alguno contra ellas", "Pueden recurrirse ante el Tribunal Supremo", "Solo vinculan a las partes del proceso", "No se publican"], "e": "Se publican en el BOE con los votos particulares, si los hay.", "r": "CE art. 164.1"}, {"id": "abat07q13", "q": "Las sentencias que declaran la inconstitucionalidad de una ley:", "o": ["Tienen plenos efectos frente a todos", "Solo afectan a las partes", "No afectan a la jurisprudencia", "Necesitan ser ratificadas por las Cortes"], "e": "Salvo que el fallo disponga otra cosa, subsiste la vigencia de la ley en la parte no afectada.", "r": "CE art. 164.1"}, {"id": "abat07q14", "q": "¿Qué ley orgánica regula el Tribunal Constitucional?", "o": ["La LO 2/1979", "La LO 6/1985", "La LO 3/1979", "La LO 4/1981"], "e": "Art. 165.", "r": "CE art. 165"}, {"id": "abat07q15", "q": "¿Quién tiene iniciativa para la reforma constitucional?", "o": ["El Gobierno, el Congreso, el Senado y las Asambleas de las Comunidades Autónomas", "Además, 500.000 ciudadanos mediante iniciativa popular", "Solo el Gobierno y las Cortes", "El Rey y el Gobierno"], "e": "Art. 166, que remite a los apartados 1 y 2 del art. 87. No cabe la iniciativa popular.", "r": "CE art. 166"}, {"id": "abat07q16", "q": "En el procedimiento ordinario de reforma constitucional, el proyecto debe aprobarse por:", "o": ["Una mayoría de tres quintos de cada una de las Cámaras", "Mayoría absoluta de cada Cámara", "Dos tercios de cada Cámara", "Mayoría simple del Congreso"], "e": "Si no hay acuerdo, se crea una Comisión paritaria de diputados y senadores.", "r": "CE art. 167.1"}, {"id": "abat07q17", "q": "Si en el procedimiento ordinario de reforma el Senado aprueba el texto por mayoría absoluta pero no por tres quintos, el Congreso puede aprobar la reforma por:", "o": ["Mayoría de dos tercios", "Mayoría absoluta", "Mayoría simple", "Unanimidad"], "e": "Art. 167.2.", "r": "CE art. 167.2"}, {"id": "abat07q18", "q": "En el procedimiento ordinario, la reforma aprobada se somete a referéndum:", "o": ["Cuando así lo solicite, dentro de los quince días siguientes, una décima parte de los miembros de cualquiera de las Cámaras", "Siempre", "Nunca", "Si lo pide el Gobierno"], "e": "Art. 167.3.", "r": "CE art. 167.3"}, {"id": "abat07q19", "q": "¿Qué partes de la Constitución exigen el procedimiento agravado del art. 168 para su reforma?", "o": ["La revisión total o la parcial que afecte al Título Preliminar, a la Sección 1.ª del Capítulo II del Título I o al Título II", "Cualquier artículo del Título I", "El Título VIII", "Los Títulos III, IV y V"], "e": "El Título II regula la Corona.", "r": "CE art. 168.1"}, {"id": "abat07q20", "q": "En el procedimiento agravado, ¿qué sucede tras aprobar el principio de la reforma por dos tercios de cada Cámara?", "o": ["Se disuelven inmediatamente las Cortes; las nuevas Cámaras ratifican la decisión y aprueban el texto por dos tercios, y después hay referéndum obligatorio", "Se celebra inmediatamente el referéndum", "El Rey sanciona la reforma", "El Tribunal Constitucional revisa el texto"], "e": "Art. 168.2 y 3.", "r": "CE art. 168"}, {"id": "abat07q21", "q": "No puede iniciarse la reforma constitucional:", "o": ["En tiempo de guerra o de vigencia de los estados de alarma, excepción o sitio", "Durante el primer año de legislatura", "Fuera del período de sesiones", "Si hay elecciones autonómicas convocadas"], "e": "Art. 169.", "r": "CE art. 169"}, {"id": "abat07q22", "q": "¿Por qué procedimiento se han hecho las tres reformas de la Constitución (1992, 2011 y 2024)?", "o": ["Por el procedimiento ordinario del art. 167, sin referéndum", "Por el procedimiento agravado del art. 168", "Por decreto-ley", "Por referéndum consultivo"], "e": "1992: art. 13.2; 2011: art. 135; 2024: art. 49.", "r": "CE art. 167"}]}, {"id": "t08", "sig": "Tema 8", "titulo": "Tema 8. El Estatuto de Autonomía del País Vasco (I): Título Preliminar y Título I (competencias)", "sub": "Parte Primera", "preguntas": [], "incluye": ["biblioteca-dfb/t02:1-15", "getxo-administrativo/t03", "getxo-kirolak-auxiliar/t03"]}, {"id": "t09", "sig": "Tema 9", "titulo": "Tema 9. El Estatuto de Autonomía del País Vasco (II): poderes, Hacienda y Patrimonio, reforma y Disposición Adicional", "sub": "Parte Primera", "preguntas": [{"id": "abat09q01", "q": "¿Por qué ley se fijan hoy en 25 por territorio (75 en total) los parlamentarios vascos?", "o": ["La Ley 5/1990, de Elecciones al Parlamento Vasco", "El propio Estatuto de Autonomía", "La LO 5/1985, de Régimen Electoral General", "La Ley 27/1983 de Territorios Históricos"], "e": "El Estatuto solo exige un número igual por cada Territorio Histórico.", "r": "EAPV art. 26 y Ley 5/1990"}, {"id": "abat09q02", "q": "Sobre la inculpación, prisión, procesamiento y juicio de los parlamentarios vascos por actos cometidos en el País Vasco decide:", "o": ["El Tribunal Superior de Justicia del País Vasco", "El Tribunal Supremo", "El propio Parlamento Vasco", "La Audiencia Nacional"], "e": "Fuera del territorio vasco, la Sala de lo Penal del Tribunal Supremo.", "r": "EAPV art. 26.6"}, {"id": "abat09q03", "q": "Las sesiones extraordinarias del Parlamento Vasco se convocan a petición de:", "o": ["El Gobierno, la Diputación Permanente o un tercio de los parlamentarios", "La mayoría absoluta del Parlamento", "El Lehendakari únicamente", "Las Juntas Generales"], "e": "Art. 27.2.", "r": "EAPV art. 27.2"}, {"id": "abat09q04", "q": "¿Quién tiene iniciativa legislativa en el Parlamento Vasco según el art. 27.4?", "o": ["Los parlamentarios, el Gobierno y las instituciones representativas de los Territorios Históricos", "Solo el Gobierno Vasco", "El Gobierno y el Lehendakari", "Las Diputaciones Forales y los Ayuntamientos"], "e": "La iniciativa popular se regula por ley del Parlamento.", "r": "EAPV art. 27.4"}, {"id": "abat09q05", "q": "¿Cuál de estas funciones corresponde al Parlamento Vasco según el art. 28?", "o": ["Designar a los senadores que corresponden a la Comunidad Autónoma", "Nombrar a los jueces del Tribunal Superior de Justicia", "Aprobar el cupo", "Nombrar al Diputado General"], "e": "También puede pedir al Gobierno del Estado un proyecto de ley, remitir proposiciones al Congreso e interponer recurso de inconstitucionalidad.", "r": "EAPV art. 28"}, {"id": "abat09q06", "q": "¿Qué ley regula el Gobierno Vasco?", "o": ["La Ley 7/1981, de Gobierno", "La Ley 27/1983", "La Ley 1/1987", "La LO 3/1979"], "e": "El Estatuto remite al Parlamento la regulación del Gobierno (art. 30).", "r": "EAPV art. 30"}, {"id": "abat09q07", "q": "La Ertzaintza, como Policía Judicial, depende de:", "o": ["La Administración de Justicia", "Las Diputaciones Forales", "El Ministerio del Interior", "El Parlamento Vasco"], "e": "Art. 36.", "r": "EAPV art. 36"}, {"id": "abat09q08", "q": "Las leyes del Parlamento Vasco solo pueden ser controladas por:", "o": ["El Tribunal Constitucional", "El Tribunal Superior de Justicia del País Vasco", "La Comisión Arbitral", "La jurisdicción contencioso-administrativa"], "e": "Los actos y reglamentos del Gobierno vasco van a la jurisdicción contencioso-administrativa.", "r": "EAPV art. 38"}, {"id": "abat09q09", "q": "¿Quién preside la Comisión Arbitral que resuelve los conflictos entre las instituciones comunes y las de los Territorios Históricos?", "o": ["El Presidente del Tribunal Superior de Justicia del País Vasco", "El Lehendakari", "El Presidente del Parlamento Vasco", "El Diputado General más antiguo"], "e": "Está formada por igual número de representantes del Gobierno Vasco y de la Diputación Foral interesada.", "r": "EAPV art. 39"}, {"id": "abat09q10", "q": "¿Quién elabora y quién aprueba los Presupuestos Generales del País Vasco?", "o": ["Los elabora el Gobierno Vasco y los aprueba el Parlamento Vasco", "Los elaboran las Diputaciones y los aprueba el Gobierno", "Los elabora el Parlamento y los aprueba el Gobierno", "Los elabora y aprueba el Gobierno"], "e": "Art. 44.", "r": "EAPV art. 44"}, {"id": "abat09q11", "q": "¿Quién puede proponer la reforma ordinaria del Estatuto (art. 46)?", "o": ["El Parlamento Vasco a propuesta de una quinta parte de sus componentes, el Gobierno Vasco o las Cortes Generales", "Solo el Gobierno Vasco", "Las Juntas Generales de los tres territorios", "50.000 ciudadanos vascos"], "e": "Art. 46.1.a.", "r": "EAPV art. 46.1.a"}, {"id": "abat09q12", "q": "En la reforma ordinaria del Estatuto, ¿qué pasos siguen a la iniciativa?", "o": ["Aprobación por el Parlamento Vasco por mayoría absoluta, aprobación por las Cortes Generales mediante ley orgánica y referéndum de los electores", "Solo la aprobación del Parlamento Vasco", "Referéndum y luego aprobación del Gobierno", "Aprobación por las Juntas Generales y el Senado"], "e": "Art. 46.1.", "r": "EAPV art. 46.1"}, {"id": "abat09q13", "q": "La reforma simplificada del art. 47.1 procede cuando:", "o": ["La reforma tenga por objeto la mera alteración de la organización de los poderes del País Vasco y no afecte a las relaciones con el Estado ni a los regímenes forales", "Afecte a las competencias del Título I", "Lo pida el Gobierno del Estado", "Se trate de incorporar Navarra"], "e": "Si en 30 días ninguna institución consultada se declara afectada, se convoca referéndum y luego se aprueba por ley orgánica.", "r": "EAPV art. 47.1"}, {"id": "abat09q14", "q": "En la reforma simplificada, ¿a quién se consulta antes del referéndum?", "o": ["A las Cortes Generales y a las Juntas Generales", "Al Tribunal Constitucional", "A los Ayuntamientos", "Al Consejo de Estado"], "e": "Disponen de 30 días para declararse afectadas.", "r": "EAPV art. 47.1"}, {"id": "abat09q15", "q": "¿Qué dice la Disposición Adicional del Estatuto de Autonomía?", "o": ["Que aceptar el régimen de autonomía no implica renuncia del Pueblo Vasco a los derechos que le pudieran corresponder por su historia", "Que el euskera es la única lengua oficial", "Que Navarra se incorpora al País Vasco", "Que el Concierto se renueva cada cinco años"], "e": "Esos derechos podrán actualizarse de acuerdo con el ordenamiento jurídico.", "r": "EAPV Disposición Adicional"}, {"id": "abat09q16", "q": "Según el art. 40 del Estatuto, para el adecuado ejercicio de sus competencias el País Vasco dispondrá de:", "o": ["Su propia Hacienda Autónoma", "Una participación en los ingresos del Estado exclusivamente", "Los ingresos de los Ayuntamientos", "Una asignación anual del Senado"], "e": "Art. 40.", "r": "EAPV art. 40"}, {"id": "abat09q17", "q": "El cupo que aporta el País Vasco al Estado se fija en:", "o": ["Una Comisión Mixta, integrada por representantes de cada Diputación Foral y del Gobierno Vasco y otros tantos del Estado, y se aprueba por ley", "Los Presupuestos Generales del Estado cada año sin negociación", "Un decreto del Gobierno Vasco", "Las Juntas Generales de cada territorio"], "e": "Con la periodicidad que se fije en el Concierto.", "r": "EAPV art. 41.2.e"}], "incluye": ["biblioteca-dfb/t02:16-32"]}, {"id": "t10", "sig": "Tema 10", "titulo": "Tema 10. Fuentes del Derecho Administrativo. La Ley: concepto y clases. El Reglamento: titularidad de la potestad reglamentaria y sus límites. Jerarquía normat", "sub": "Parte Segunda", "preguntas": [], "incluye": ["getxo-administrativo/t04"]}, {"id": "t11", "sig": "Tema 11", "titulo": "Tema 11. La Administración Pública en el Ordenamiento. Clases de Administraciones Públicas. Principios de actuación. El principio de legalidad. Potestades admi", "sub": "Parte Segunda", "preguntas": [{"id": "abat11q01", "q": "¿Qué artículo de la Constitución establece que la Administración Pública sirve con objetividad los intereses generales?", "o": ["El art. 103.1", "El art. 97", "El art. 106.1", "El art. 9.1"], "e": "Con sometimiento pleno a la ley y al Derecho.", "r": "CE art. 103.1"}, {"id": "abat11q02", "q": "Según el art. 3.4 de la Ley 40/2015, cada una de las Administraciones Públicas actúa para el cumplimiento de sus fines con:", "o": ["Personalidad jurídica única", "Varias personalidades jurídicas, una por órgano", "Personalidad jurídica limitada", "Sin personalidad jurídica propia"], "e": "Es uno de los rasgos de la Administración.", "r": "Ley 40/2015 art. 3.4"}, {"id": "abat11q03", "q": "Según la Ley 40/2015, ¿cuál de estas entidades tiene la consideración de Administración Pública?", "o": ["Un organismo autónomo dependiente de una Comunidad Autónoma", "Una sociedad mercantil municipal", "Una fundación del sector público", "Un colegio profesional en todo caso"], "e": "Son Administraciones las territoriales y los organismos públicos y entidades de derecho público vinculados o dependientes.", "r": "Ley 40/2015 art. 2.3"}, {"id": "abat11q04", "q": "Los colegios profesionales y las cámaras de comercio son ejemplos de Administraciones:", "o": ["Corporativas", "Territoriales", "Institucionales", "Independientes"], "e": "Tienen base asociativa y ejercen funciones públicas atribuidas por la ley.", "r": "Clases de Administraciones"}, {"id": "abat11q05", "q": "Osakidetza, Lanbide o el IVAP son ejemplos de Administración:", "o": ["Institucional", "Territorial", "Corporativa", "Local"], "e": "Persiguen fines específicos y dependen de una Administración territorial.", "r": "Clases de Administraciones"}, {"id": "abat11q06", "q": "El traspaso de competencias a otra persona jurídica (por ejemplo, del Estado a las Comunidades Autónomas) se llama:", "o": ["Descentralización", "Desconcentración", "Delegación de firma", "Avocación"], "e": "La desconcentración es el traspaso a órganos inferiores de la misma Administración.", "r": "CE art. 103.1"}, {"id": "abat11q07", "q": "La desconcentración consiste en:", "o": ["Atribuir competencias a órganos jerárquicamente dependientes de la misma Administración", "Transferir competencias a otra Administración", "Recuperar una competencia delegada", "Crear un organismo autónomo"], "e": "Se regula en el art. 8.2 de la Ley 40/2015.", "r": "Ley 40/2015 art. 8.2"}, {"id": "abat11q08", "q": "¿Cuál de estos NO es un principio general de actuación del art. 3.1 de la Ley 40/2015?", "o": ["Rentabilidad económica de los servicios", "Buena fe, confianza legítima y lealtad institucional", "Simplicidad, claridad y proximidad a los ciudadanos", "Eficiencia en la asignación y utilización de los recursos públicos"], "e": "También: servicio efectivo, participación, objetividad y transparencia, racionalización, responsabilidad y cooperación.", "r": "Ley 40/2015 art. 3.1"}, {"id": "abat11q09", "q": "Según el art. 3.2 de la Ley 40/2015, las Administraciones se relacionan entre sí por:", "o": ["Medios electrónicos que aseguren la interoperabilidad y seguridad de los sistemas", "Correo postal certificado", "Cualquier medio, a su elección", "Medios presenciales en todo caso"], "e": "Art. 3.2.", "r": "Ley 40/2015 art. 3.2"}, {"id": "abat11q10", "q": "El principio de vinculación positiva de la Administración a la ley significa que:", "o": ["La Administración solo puede hacer lo que el ordenamiento le permite", "La Administración puede hacer todo lo que la ley no le prohíbe", "La Administración puede inaplicar las leyes que considere injustas", "Los particulares solo pueden hacer lo que la ley les permite"], "e": "Los particulares, en cambio, pueden hacer todo lo que la ley no prohíbe.", "r": "Principio de legalidad"}, {"id": "abat11q11", "q": "¿Cuál de estos artículos de la Constitución NO es una manifestación del principio de legalidad de la Administración?", "o": ["El art. 2", "El art. 9.1", "El art. 103.1", "El art. 106.1"], "e": "El art. 2 trata de la unidad de la Nación y el derecho a la autonomía.", "r": "CE arts. 9, 103 y 106"}, {"id": "abat11q12", "q": "¿Cuál de estas características corresponde a una potestad administrativa?", "o": ["Es irrenunciable e imprescriptible", "Nace de un contrato", "Se agota con su ejercicio", "Es renunciable por la Administración"], "e": "Además, procede directamente de la ley y es genérica.", "r": "Potestades administrativas"}, {"id": "abat11q13", "q": "¿Cuál de estas es una diferencia entre potestad y derecho subjetivo?", "o": ["El derecho subjetivo es renunciable y puede prescribir; la potestad no", "La potestad nace de una relación jurídica concreta", "El derecho subjetivo procede siempre de la ley", "La potestad se agota al ejercerla"], "e": "El derecho subjetivo nace de relaciones concretas y tiene un objeto determinado.", "r": "Potestades administrativas"}, {"id": "abat11q14", "q": "¿Qué artículo de la LBRL enumera las potestades de los municipios, provincias e islas?", "o": ["El art. 4", "El art. 25", "El art. 22", "El art. 1"], "e": "Reglamentaria y de autoorganización, tributaria y financiera, de programación, expropiatoria, de investigación, deslinde y recuperación de oficio de bienes, entre otras.", "r": "LBRL art. 4"}, {"id": "abat11q15", "q": "La medida de la potestad que corresponde a cada órgano se llama:", "o": ["Competencia", "Jerarquía", "Delegación", "Discrecionalidad"], "e": "Es irrenunciable y se ejerce por el órgano que la tiene atribuida, salvo delegación o avocación.", "r": "Ley 40/2015 art. 8"}, {"id": "abat11q16", "q": "En la potestad reglada:", "o": ["La ley fija todas las condiciones y la consecuencia, y la Administración solo comprueba el supuesto y aplica la norma", "La Administración elige entre varias soluciones igualmente válidas", "La Administración actúa según criterios de oportunidad", "No hay control judicial"], "e": "Ejemplo: conceder una licencia si el proyecto cumple el planeamiento.", "r": "Potestad reglada"}, {"id": "abat11q17", "q": "En la potestad discrecional:", "o": ["La ley deja a la Administración un margen para elegir entre varias soluciones igualmente válidas", "La Administración puede actuar sin sujeción a la ley", "No es necesario motivar", "No existe ningún control judicial"], "e": "Discrecionalidad no es arbitrariedad (art. 9.3 CE).", "r": "Potestad discrecional"}, {"id": "abat11q18", "q": "Los actos dictados en el ejercicio de potestades discrecionales:", "o": ["Deben ser motivados", "No necesitan motivación", "Solo se motivan si lo pide el interesado", "Solo se motivan si son desfavorables"], "e": "Art. 35.1.i de la Ley 39/2015.", "r": "Ley 39/2015 art. 35.1.i"}, {"id": "abat11q19", "q": "Usar una potestad para fines distintos de los fijados por el ordenamiento jurídico es:", "o": ["Desviación de poder", "Inderogabilidad singular", "Silencio administrativo", "Avocación"], "e": "Es causa de anulabilidad (art. 48.1 de la Ley 39/2015).", "r": "Ley 39/2015 art. 48.1"}, {"id": "abat11q20", "q": "¿Cuál de estos elementos de una potestad discrecional es siempre reglado y controlable por los tribunales?", "o": ["La competencia del órgano y el fin", "La oportunidad de la decisión", "La elección entre varias soluciones válidas", "El criterio político"], "e": "También la existencia de la potestad, su extensión y el procedimiento.", "r": "Control de la discrecionalidad"}, {"id": "abat11q21", "q": "Los conceptos jurídicos indeterminados (como «urgencia» o «justo precio»):", "o": ["No son discrecionalidad: admiten una sola solución justa en el caso concreto", "Son una forma de potestad discrecional", "No pueden ser controlados por los tribunales", "Permiten a la Administración elegir libremente"], "e": "Aunque existe un «halo» o margen de apreciación.", "r": "Conceptos jurídicos indeterminados"}, {"id": "abat11q22", "q": "¿Qué artículo de la Constitución atribuye a los Tribunales el control de la legalidad de la actuación administrativa?", "o": ["El art. 106.1", "El art. 103.1", "El art. 97", "El art. 24"], "e": "El art. 106.2 reconoce la responsabilidad patrimonial de la Administración.", "r": "CE art. 106"}]}, {"id": "t12", "sig": "Tema 12", "titulo": "Tema 12. Ley 39/2015 (I): los interesados en el procedimiento (Título I)", "sub": "Parte Segunda", "preguntas": [], "incluye": ["getxo-administrativo/t09"]}, {"id": "t13", "sig": "Tema 13", "titulo": "Tema 13. Ley 39/2015 (II): la actividad de las Administraciones Públicas (Título II). Normas generales de actuación y términos y plazos", "sub": "Parte Segunda", "preguntas": [], "incluye": ["biblioteca-dfb/t06", "getxo-administrativo/t10", "getxo-administrativo/t11"]}, {"id": "t14", "sig": "Tema 14", "titulo": "Tema 14. Ley 39/2015 (III): los actos administrativos (Título III)", "sub": "Parte Segunda", "preguntas": [], "incluye": ["getxo-administrativo/t12"]}, {"id": "t15", "sig": "Tema 15", "titulo": "Tema 15. Ley 39/2015 (IV): el procedimiento administrativo común (Título IV)", "sub": "Parte Segunda", "preguntas": [], "incluye": ["biblioteca-dfb/ay09", "getxo-administrativo/t13", "getxo-administrativo/t14", "getxo-administrativo/t15"]}, {"id": "t16", "sig": "Tema 16", "titulo": "Tema 16. Ley 39/2015 (V): la revisión de los actos en vía administrativa (Título V)", "sub": "Parte Segunda", "preguntas": [], "incluye": ["getxo-administrativo/t16"]}, {"id": "t17", "sig": "Tema 17", "titulo": "Tema 17. Ley 40/2015 (I): disposiciones generales, órganos de las Administraciones y responsabilidad patrimonial (Título Preliminar, Caps. I, II y IV)", "sub": "Parte Segunda", "preguntas": [], "incluye": ["getxo-administrativo/t17", "getxo-administrativo/t18:13-30"]}, {"id": "t18", "sig": "Tema 18", "titulo": "Tema 18. Ley 40/2015 (II): funcionamiento electrónico del sector público (Cap. V) y convenios (Cap. VI)", "sub": "Parte Segunda", "preguntas": [{"id": "abat18q01", "q": "Según el art. 47 de la Ley 40/2015, los convenios son:", "o": ["Acuerdos con efectos jurídicos adoptados por las Administraciones, organismos públicos, universidades públicas o entre ellos y sujetos privados, para un fin común", "Contratos administrativos de obras o servicios", "Declaraciones de intención sin efectos jurídicos", "Tratados internacionales"], "e": "No tienen la consideración de convenios los protocolos generales de actuación que solo expresan la voluntad de actuar con un objetivo común.", "r": "Ley 40/2015 art. 47.1"}, {"id": "abat18q02", "q": "Los convenios no pueden tener por objeto:", "o": ["Prestaciones propias de los contratos, que se rigen por la legislación de contratos del sector público", "Fines comunes de varias Administraciones", "La utilización conjunta de medios", "Actividades de utilidad pública"], "e": "Art. 47.1.", "r": "Ley 40/2015 art. 47.1"}, {"id": "abat18q03", "q": "Los convenios entre organismos públicos y entidades de derecho público vinculados o dependientes de una misma Administración se llaman:", "o": ["Intradministrativos", "Interadministrativos", "Con sujetos de derecho privado", "No normativos"], "e": "Los interadministrativos se firman entre dos o más Administraciones.", "r": "Ley 40/2015 art. 47.2"}, {"id": "abat18q04", "q": "La suscripción de convenios, según el art. 48:", "o": ["No puede suponer cesión de la titularidad de la competencia", "Implica siempre la cesión de la competencia", "Requiere autorización de las Cortes", "Solo es posible entre Administraciones del mismo nivel"], "e": "Se suscriben en el ámbito de las propias competencias.", "r": "Ley 40/2015 art. 48.1"}, {"id": "abat18q05", "q": "Las aportaciones financieras de las partes de un convenio:", "o": ["No pueden ser superiores a los gastos derivados de su ejecución", "Pueden superar los gastos para crear un fondo", "Deben ser siempre iguales para todas las partes", "No están limitadas"], "e": "Art. 48.6.", "r": "Ley 40/2015 art. 48.6"}, {"id": "abat18q06", "q": "Los convenios se perfeccionan:", "o": ["Por la prestación del consentimiento de las partes", "Por su publicación en el boletín oficial", "Por su inscripción en un registro", "Por la aprobación del Pleno"], "e": "Los de la AGE son eficaces una vez inscritos en el registro estatal de órganos e instrumentos de cooperación.", "r": "Ley 40/2015 art. 48.8"}, {"id": "abat18q07", "q": "¿Cuál es el plazo máximo de vigencia de un convenio, salvo que una norma establezca otro?", "o": ["Cuatro años", "Dos años", "Cinco años", "Diez años"], "e": "Antes de que termine, los firmantes pueden acordar por unanimidad su prórroga por hasta cuatro años adicionales o su extinción.", "r": "Ley 40/2015 art. 49.h"}, {"id": "abat18q08", "q": "Si un convenio no regula su modificación, esta requiere:", "o": ["Acuerdo unánime de los firmantes", "Mayoría de los firmantes", "Decisión de la Administración que lo promovió", "Autorización judicial"], "e": "Art. 49.g.", "r": "Ley 40/2015 art. 49.g"}, {"id": "abat18q09", "q": "¿Cuál de estos contenidos NO es obligatorio en un convenio según el art. 49?", "o": ["El nombre de las personas que lo ejecutarán", "El objeto y las actuaciones de cada parte", "Las obligaciones y compromisos económicos", "Los mecanismos de seguimiento, vigilancia y control"], "e": "También: sujetos, competencia, consecuencias del incumplimiento, régimen de modificación y plazo de vigencia.", "r": "Ley 40/2015 art. 49"}, {"id": "abat18q10", "q": "La suscripción de un convenio debe acompañarse de:", "o": ["Una memoria justificativa de su necesidad y oportunidad, su impacto económico y su carácter no contractual", "Un informe del Tribunal de Cuentas", "Una autorización del Consejo de Ministros en todo caso", "Un acuerdo de las Cortes Generales"], "e": "Art. 50.1.", "r": "Ley 40/2015 art. 50.1"}, {"id": "abat18q11", "q": "¿Cuál de estas es una causa de resolución de un convenio según el art. 51?", "o": ["El incumplimiento de las obligaciones por alguno de los firmantes, tras requerirle su cumplimiento", "El cambio de titular del órgano firmante", "La celebración de elecciones", "La falta de publicación en el boletín"], "e": "También el transcurso del plazo sin prórroga, el acuerdo unánime, la declaración judicial de nulidad y otras causas previstas.", "r": "Ley 40/2015 art. 51.2"}, {"id": "abat18q12", "q": "Los convenios con compromisos económicos superiores a 600.000 euros deben remitirse al Tribunal de Cuentas u órgano externo de fiscalización:", "o": ["En los tres meses siguientes a su suscripción", "En el mes siguiente", "Antes de su firma", "Al terminar su vigencia"], "e": "En Euskadi, el órgano externo es el Tribunal Vasco de Cuentas Públicas.", "r": "Ley 40/2015 art. 53"}, {"id": "abat18q13", "q": "Cuando se resuelve un convenio, las actuaciones en curso:", "o": ["Pueden continuar hasta la fecha límite que acuerden las partes a propuesta de la comisión de seguimiento", "Se paralizan de inmediato en todo caso", "Se transfieren al Tribunal de Cuentas", "Pasan a regirse por la Ley de Contratos"], "e": "Tras la resolución se liquida el convenio para determinar las obligaciones de cada parte.", "r": "Ley 40/2015 art. 52"}, {"id": "abat18q14", "q": "Los protocolos generales de actuación:", "o": ["No son convenios: expresan la voluntad de actuar con un objetivo común sin compromisos jurídicos concretos y exigibles", "Son convenios intradministrativos", "Son contratos menores", "Deben inscribirse en el registro de convenios"], "e": "Art. 47.1.", "r": "Ley 40/2015 art. 47.1"}], "incluye": ["getxo-administrativo/t19"]}, {"id": "t19", "sig": "Tema 19", "titulo": "Tema 19. Ley Orgánica 3/2018, de Protección de Datos Personales y garantía de los derechos digitales (Títulos I, II y III)", "sub": "Parte Segunda", "preguntas": [], "incluye": ["getxo-administrativo/t07"]}, {"id": "t20", "sig": "Tema 20", "titulo": "Tema 20. Ley 38/2003, de 17 de noviembre, General de Subvenciones", "sub": "Parte Segunda", "preguntas": [], "incluye": ["getxo-administrativo/t36", "getxo-administrativo/t37"]}, {"id": "t21", "sig": "Tema 21", "titulo": "Tema 21. Decreto Legislativo 1/2023: texto refundido de la Ley para la Igualdad de Mujeres y Hombres y Vidas Libres de Violencia Machista contra las Mujeres (T", "sub": "Parte Segunda", "preguntas": [], "incluye": ["biblioteca-dfb/t09:1-12", "getxo-kirolak-auxiliar/t05:35-48"]}, {"id": "t22", "sig": "Tema 22", "titulo": "Tema 22. Ley 9/2017, de Contratos del Sector Público (I): objeto, ámbito y tipos de contratos", "sub": "Parte Segunda", "preguntas": [], "incluye": ["getxo-administrativo/t32"]}, {"id": "t23", "sig": "Tema 23", "titulo": "Tema 23. Ley 9/2017, de Contratos del Sector Público (II): objeto, presupuesto base de licitación, valor estimado y precio (Libro I, Título III, Cap. I)", "sub": "Parte Segunda", "preguntas": [], "incluye": ["getxo-administrativo/t33"]}, {"id": "t24", "sig": "Tema 24", "titulo": "Tema 24. Ley 9/2017, de Contratos del Sector Público (III): el expediente de contratación y los pliegos (arts. 116–124)", "sub": "Parte Segunda", "preguntas": [], "incluye": ["getxo-administrativo/t34"]}, {"id": "t25", "sig": "Tema 25", "titulo": "Tema 25. Ley 11/2022, de Empleo Público Vasco (I): disposiciones generales, clases de personal, estructura y adquisición y pérdida de la condición", "sub": "Parte Segunda", "preguntas": [], "incluye": ["biblioteca-dfb/t07"]}, {"id": "t26", "sig": "Tema 26", "titulo": "Tema 26. Ley 11/2022, de Empleo Público Vasco (II): selección (Título VI, Cap. I), carrera profesional (Título VII) y situaciones administrativas (Título X)", "sub": "Parte Segunda", "preguntas": [{"id": "abat26q01", "q": "Según la Ley 11/2022, la carrera profesional es:", "o": ["El conjunto ordenado de oportunidades de ascenso, movilidad y progreso profesional conforme a los principios de igualdad, mérito y capacidad", "El tiempo de servicios prestados en la Administración", "El sistema de acceso al empleo público", "El conjunto de retribuciones complementarias"], "e": "Es un derecho del personal funcionario de carrera y un instrumento de gestión.", "r": "Ley 11/2022 art. 85"}, {"id": "abat26q02", "q": "La carrera vertical consiste en:", "o": ["El ascenso en la estructura de puestos de trabajo mediante los procedimientos de provisión", "La progresión de grado sin cambiar de puesto", "El ascenso al subgrupo inmediatamente superior", "El acceso a otro cuerpo del mismo subgrupo"], "e": "Se hace mediante concurso o libre designación, dentro del mismo grupo o subgrupo.", "r": "Ley 11/2022 art. 87"}, {"id": "abat26q03", "q": "La carrera horizontal consiste en:", "o": ["La progresión de grado de desarrollo profesional sin necesidad de cambiar de puesto de trabajo", "El cambio de puesto por concurso", "El acceso a un cuerpo del subgrupo superior", "La movilidad entre Administraciones"], "e": "Requiere evaluación favorable de méritos y del desempeño, y depende de la disponibilidad presupuestaria.", "r": "Ley 11/2022 arts. 88 a 90"}, {"id": "abat26q04", "q": "La promoción interna vertical es:", "o": ["El ascenso desde un cuerpo o escala de un subgrupo al inmediatamente superior", "El acceso a cuerpos o escalas del mismo subgrupo", "La progresión de grado", "El cambio de puesto por libre designación"], "e": "La horizontal es el acceso a cuerpos o escalas del mismo subgrupo.", "r": "Ley 11/2022 arts. 92 y 93"}, {"id": "abat26q05", "q": "Para participar en la promoción interna se exige haber completado en el cuerpo, escala o agrupación de origen:", "o": ["Dos años de servicios", "Un año de servicios", "Tres años de servicios", "Cinco años de servicios"], "e": "Además, estar en servicio activo, servicios especiales o ciertas excedencias, y tener la titulación exigida.", "r": "Ley 11/2022 art. 91"}, {"id": "abat26q06", "q": "En la carrera horizontal, ¿a qué grado se puede progresar?", "o": ["Solo al grado inmediatamente superior", "A cualquier grado superior", "Directamente al grado máximo", "A un grado de otro subgrupo"], "e": "Se empieza en el grado mínimo del grupo o subgrupo.", "r": "Ley 11/2022 art. 89"}, {"id": "abat26q07", "q": "¿Cuál de estas es una situación administrativa del personal funcionario de carrera según el art. 136?", "o": ["Servicios especiales", "Comisión de servicios", "Adscripción provisional", "Incapacidad temporal"], "e": "La comisión de servicios y la incapacidad temporal se dan dentro del servicio activo.", "r": "Ley 11/2022 arts. 136 y 137"}, {"id": "abat26q08", "q": "Un funcionario que disfruta de vacaciones, permisos o incapacidad temporal está en situación de:", "o": ["Servicio activo", "Servicios especiales", "Excedencia voluntaria", "Suspensión de funciones"], "e": "Art. 137.", "r": "Ley 11/2022 art. 137"}, {"id": "abat26q09", "q": "Un funcionario elegido concejal con dedicación exclusiva pasa a la situación de:", "o": ["Servicios especiales", "Excedencia voluntaria por interés particular", "Servicio en otras Administraciones", "Excedencia forzosa"], "e": "También los miembros del Gobierno, altos cargos, parlamentarios o junteros, entre otros supuestos.", "r": "Ley 11/2022 art. 138"}, {"id": "abat26q10", "q": "Al cesar en servicios especiales, ¿de qué plazo dispone el funcionario para pedir el reingreso al servicio activo?", "o": ["Treinta días naturales", "Diez días hábiles", "Un mes", "Tres meses"], "e": "Si no lo pide, pasa a excedencia voluntaria por interés particular.", "r": "Ley 11/2022 art. 138"}, {"id": "abat26q11", "q": "Para pedir la excedencia voluntaria por interés particular hay que haber prestado servicios efectivos durante:", "o": ["Dos años continuados inmediatamente anteriores", "Un año", "Tres años", "Cinco años"], "e": "La permanencia mínima en la excedencia es de dos años y no hay reserva de puesto.", "r": "Ley 11/2022 art. 141"}, {"id": "abat26q12", "q": "En la excedencia voluntaria por interés particular:", "o": ["No se devengan retribuciones ni computa el tiempo para carrera, trienios ni Seguridad Social", "Se mantiene el 50 % de las retribuciones", "Se reserva el puesto dos años", "Computa a efectos de trienios"], "e": "Está supeditada a las necesidades del servicio.", "r": "Ley 11/2022 art. 141"}, {"id": "abat26q13", "q": "La excedencia voluntaria con reserva de puesto y destino tiene una duración:", "o": ["De entre seis meses y un año", "De un mínimo de dos años", "De hasta tres años", "Indefinida"], "e": "Exige tres años de servicios continuados; durante ella no se puede trabajar en el sector público.", "r": "Ley 11/2022 art. 142"}, {"id": "abat26q14", "q": "La excedencia por cuidado de cada hijo o familiar dura:", "o": ["Hasta tres años por cada sujeto causante, con reserva del puesto", "Hasta un año, sin reserva", "Hasta dos años, con reserva de un año", "Un máximo de seis meses"], "e": "Computa para trienios y Seguridad Social, y es un derecho individual que puede fraccionarse.", "r": "Ley 11/2022 art. 144"}, {"id": "abat26q15", "q": "En la excedencia por razón de violencia de género, la funcionaria tiene derecho a la reserva del puesto durante:", "o": ["Seis meses, prorrogables por periodos de tres meses hasta un máximo de dieciocho", "Un año, sin prórroga", "Tres años", "Dos meses"], "e": "Durante los primeros seis meses percibe las retribuciones íntegras.", "r": "Ley 11/2022 art. 145"}, {"id": "abat26q16", "q": "La excedencia voluntaria incentivada supone no poder trabajar en el sector público durante:", "o": ["Cinco años", "Dos años", "Tres años", "Un año"], "e": "La indemnización es de una mensualidad por año de servicio, con un máximo de 24.", "r": "Ley 11/2022 art. 147"}, {"id": "abat26q17", "q": "¿Cuál es la duración máxima de la situación de expectativa de destino?", "o": ["Un año", "Seis meses", "Tres años", "Dos años"], "e": "Después se pasa a la excedencia forzosa temporal (máximo tres años) y luego a la excedencia forzosa.", "r": "Ley 11/2022 arts. 149 a 151"}, {"id": "abat26q18", "q": "¿Cuál es la duración máxima de la suspensión provisional de funciones en un expediente disciplinario?", "o": ["Seis meses, salvo paralización imputable al interesado", "Tres meses", "Un año", "Toda la duración del expediente"], "e": "En el proceso penal puede durar toda la causa.", "r": "Ley 11/2022 art. 154"}, {"id": "abat26q19", "q": "La suspensión firme de funciones por sanción disciplinaria no puede exceder de:", "o": ["Seis años", "Tres años", "Un año", "Diez años"], "e": "Si supera seis meses, supone la pérdida del puesto de trabajo.", "r": "Ley 11/2022 art. 155"}, {"id": "abat26q20", "q": "¿En qué situaciones administrativas puede estar el personal funcionario interino?", "o": ["Servicio activo, suspensión de funciones y algunas excedencias (cuidado de familiares y violencia de género o terrorista)", "En todas las del personal de carrera", "Solo en servicio activo", "En servicios especiales y excedencia por interés particular"], "e": "Art. 159.", "r": "Ley 11/2022 art. 159"}, {"id": "abat26q21", "q": "En el concurso-oposición, la fase de concurso:", "o": ["No puede superar el 45 % de la puntuación máxima de la oposición ni determinar por sí sola el resultado", "Puede valer más que la oposición", "Supone siempre el 50 %", "Es eliminatoria"], "e": "Es un límite del art. 78.", "r": "Ley 11/2022 art. 78"}, {"id": "abat26q22", "q": "Las plazas de una oferta de empleo público pueden incrementarse por vacantes surgidas después de su aprobación hasta:", "o": ["Un 10 % adicional", "Un 20 % adicional", "Un 5 % adicional", "No pueden incrementarse"], "e": "Art. 78.", "r": "Ley 11/2022 art. 78"}], "incluye": ["getxo-administrativo/t23"]}, {"id": "t27", "sig": "Tema 27", "titulo": "Tema 27. Ley 11/2022, de Empleo Público Vasco (III): derechos, deberes, código de conducta, incompatibilidades y responsabilidades (Título XI)", "sub": "Parte Segunda", "preguntas": [], "incluye": ["getxo-administrativo/t24"]}, {"id": "t28", "sig": "Tema 28", "titulo": "Tema 28. Ley 10/1982, de 24 de noviembre, básica de normalización del uso del Euskera: Título Preliminar y Título I", "sub": "Parte Segunda", "preguntas": [], "incluye": ["biblioteca-dfb/t08:1-15", "getxo-kirolak-auxiliar/t04"]}, {"id": "t29", "sig": "Tema 29", "titulo": "Tema 29. Ley 7/1985, de Bases del Régimen Local (I): Título I y municipio, territorio y población (arts. 1–18). Reglamento de Población (RD 1690/1986): el padr", "sub": "Parte Tercera", "preguntas": [], "incluye": ["biblioteca-dfb/ay07:1-13", "getxo-administrativo/t25", "getxo-administrativo/t27"]}, {"id": "t30", "sig": "Tema 30", "titulo": "Tema 30. Ley 2/2016, de Instituciones Locales de Euskadi (I): objeto y principios, el municipio, otras entidades locales y competencias municipales (Títulos I,", "sub": "Parte Tercera", "preguntas": [{"id": "abat30q01", "q": "¿En qué boletín y fecha se publicó la Ley 2/2016, de Instituciones Locales de Euskadi?", "o": ["En el BOPV nº 70, de 14 de abril de 2016", "En el BOE de 7 de abril de 2016", "En el BOB de 14 de abril de 2016", "En el BOPV de 7 de abril de 2016"], "e": "La ley es de 7 de abril de 2016 y tiene 121 artículos.", "r": "Ley 2/2016, datos generales"}, {"id": "abat30q02", "q": "¿Qué títulos competenciales cita el art. 3 de la Ley 2/2016?", "o": ["La Disposición Adicional 1.ª de la Constitución, el Estatuto de Autonomía y la Ley del Concierto Económico", "Solo el art. 149.1.18.ª de la Constitución", "La Ley 7/1985 de Bases del Régimen Local", "La Carta Europea de Autonomía Local exclusivamente"], "e": "Sin perjuicio de las competencias de los Territorios Históricos.", "r": "Ley 2/2016 art. 3"}, {"id": "abat30q03", "q": "Según el art. 8 de la Ley 2/2016, el municipio es:", "o": ["La entidad local básica de la Comunidad Autónoma de Euskadi, con legitimidad democrática directa, y el cauce de participación ciudadana en los asuntos públicos locales", "Un órgano de la Diputación Foral", "La entidad local básica solo en los territorios de Bizkaia y Gipuzkoa", "Una división administrativa del Gobierno Vasco"], "e": "Art. 8.", "r": "Ley 2/2016 art. 8"}, {"id": "abat30q04", "q": "Según la Ley 2/2016, la autonomía local tiene contenido:", "o": ["Político, porque permite definir y ejecutar políticas propias, no solo prestar servicios", "Solo administrativo", "Solo económico", "Solo de ejecución de leyes autonómicas"], "e": "Art. 9.", "r": "Ley 2/2016 art. 9"}, {"id": "abat30q05", "q": "¿Dónde se lleva el registro único de entidades locales de Euskadi?", "o": ["En la Administración General de la Comunidad Autónoma", "En cada Diputación Foral", "En el Ministerio de Política Territorial", "En Eudel"], "e": "Las inscripciones se comunican al Territorio Histórico.", "r": "Ley 2/2016 art. 11"}, {"id": "abat30q06", "q": "La Ley 2/2016 garantiza la existencia de los concejos, las hermandades y las cuadrillas de:", "o": ["Álava", "Bizkaia", "Gipuzkoa", "Los tres Territorios Históricos"], "e": "Art. 12.", "r": "Ley 2/2016 art. 12"}, {"id": "abat30q07", "q": "Las competencias normativas, ejecutivas y económico-financieras sobre las entidades locales menores corresponden a:", "o": ["Los órganos forales", "El Gobierno Vasco", "Los municipios en que se integran", "El Parlamento Vasco"], "e": "Art. 13.", "r": "Ley 2/2016 art. 13"}, {"id": "abat30q08", "q": "Según el art. 14 de la Ley 2/2016, las competencias de las entidades locales son:", "o": ["Propias, transferidas o delegadas", "Exclusivas, compartidas o concurrentes", "Propias o impropias", "Obligatorias o voluntarias"], "e": "Las transferidas y delegadas tienen carácter excepcional.", "r": "Ley 2/2016 art. 14"}, {"id": "abat30q09", "q": "¿Qué facultades puede incluir una competencia según el art. 15 de la Ley 2/2016?", "o": ["Normativas o de ordenación, de planificación, de programación, de fomento y de gestión o ejecución", "Solo de gestión", "Solo normativas", "Solo de fomento"], "e": "Atribuir una competencia conlleva todas esas facultades, salvo que la ley diga otra cosa.", "r": "Ley 2/2016 art. 15"}, {"id": "abat30q10", "q": "La cláusula universal de competencias del art. 16 permite a los municipios desarrollar actividades no atribuidas siempre que:", "o": ["No estén reservadas a otros niveles de gobierno, no haya duplicidad y se cumpla la sostenibilidad financiera", "Lo autorice el Gobierno Vasco", "Lo apruebe la Diputación Foral", "Se financien con transferencias autonómicas"], "e": "Hay duplicidad cuando se ejercen las mismas funciones sobre la misma materia en el mismo territorio.", "r": "Ley 2/2016 art. 16"}, {"id": "abat30q11", "q": "¿En cuántos ámbitos materiales enumera el art. 17 de la Ley 2/2016 las competencias propias de los municipios?", "o": ["37", "25", "18", "41"], "e": "Es un mínimo garantizado.", "r": "Ley 2/2016 art. 17"}, {"id": "abat30q12", "q": "¿Cuál de estas materias es competencia propia de los municipios según el art. 17 de la Ley 2/2016?", "o": ["Planes de normalización y fomento del euskera", "Legislación laboral", "Policía autonómica", "Carreteras forales"], "e": "También urbanismo, servicios sociales, deporte, cultura, igualdad o cooperación para el desarrollo, entre otras.", "r": "Ley 2/2016 art. 17.1"}, {"id": "abat30q13", "q": "Las competencias propias de los municipios solo pueden atribuirse por:", "o": ["Ley del Parlamento Vasco o norma foral", "Decreto del Gobierno Vasco", "Ordenanza municipal", "Acuerdo de Eudel"], "e": "La ley debe incluir en un anexo la dotación de recursos necesaria.", "r": "Ley 2/2016 art. 18"}, {"id": "abat30q14", "q": "La delegación de competencias en los municipios es nula si:", "o": ["No va acompañada de la dotación que garantice la prestación de los servicios delegados", "No se publica en el BOE", "El municipio tiene menos de 5.000 habitantes", "No la aprueba el Parlamento"], "e": "Además, exige la aceptación expresa de la entidad local.", "r": "Ley 2/2016 art. 23"}, {"id": "abat30q15", "q": "La transferencia de competencias a los municipios se hace mediante:", "o": ["Ley del Parlamento Vasco o norma foral", "Acuerdo del Consejo de Gobierno", "Convenio con el municipio", "Decreto del Lehendakari"], "e": "La delegación, en cambio, se hace por disposición o acuerdo del Gobierno Vasco o de los órganos forales.", "r": "Ley 2/2016 arts. 21 y 22"}, {"id": "abat30q16", "q": "Si la Administración autonómica o foral no paga lo comprometido en una delegación o convenio, ¿quién puede retener las cantidades y abonarlas a los municipios?", "o": ["El Consejo Vasco de Finanzas Públicas", "El Tribunal Vasco de Cuentas Públicas", "El Ararteko", "La Comisión Arbitral"], "e": "Las abona en los tres primeros meses del ejercicio siguiente (art. 24).", "r": "Ley 2/2016 art. 24"}, {"id": "abat30q17", "q": "Los municipios pueden constituir fórmulas asociativas como:", "o": ["Mancomunidades y consorcios", "Diputaciones Forales", "Cuadrillas en Bizkaia", "Juntas Generales"], "e": "Forma parte de su potestad de autoorganización (art. 10).", "r": "Ley 2/2016 art. 10"}], "incluye": ["biblioteca-dfb/ay07:14-24"]}, {"id": "t31", "sig": "Tema 31", "titulo": "Tema 31. Ley 2/2016, de Instituciones Locales de Euskadi (II): derechos y deberes de las personas vecinas, cartas de servicios y gobierno abierto (Título V y T", "sub": "Parte Tercera", "preguntas": [{"id": "abat31q01", "q": "¿Cuál de estos es un derecho de las personas vecinas según el art. 43 de la Ley 2/2016?", "o": ["Ser atendidas en euskera o en castellano", "No pagar tasas municipales", "Elegir al secretario municipal", "No inscribirse en el padrón"], "e": "También ser electoras y elegibles, participar en las políticas locales, disfrutar de un medio ambiente adecuado o acceder en igualdad a los servicios públicos.", "r": "Ley 2/2016 art. 43.1"}, {"id": "abat31q02", "q": "Los derechos de las personas vecinas del art. 43, salvo los electorales, alcanzan también a:", "o": ["Las personas extranjeras empadronadas y a los menores, según la legislación sectorial", "Solo a los mayores de edad", "Solo a los españoles empadronados", "A cualquier visitante del municipio"], "e": "Art. 43.2.", "r": "Ley 2/2016 art. 43.2"}, {"id": "abat31q03", "q": "¿Cuál de estos es un deber de las personas vecinas según el art. 44?", "o": ["Comunicar las variaciones que afecten a sus datos del padrón", "Participar obligatoriamente en todas las consultas", "Pertenecer a una asociación vecinal", "Asistir a los plenos"], "e": "También contribuir con las prestaciones legalmente previstas y cumplir la normativa local.", "r": "Ley 2/2016 art. 44.1"}, {"id": "abat31q04", "q": "Los deberes del art. 44, salvo el relativo al padrón, se aplican también a:", "o": ["Quienes, sin ser vecinos, se encuentren en el municipio", "Solo a los vecinos mayores de edad", "Solo a los propietarios de inmuebles", "A los vecinos de los municipios limítrofes"], "e": "Art. 44.2.", "r": "Ley 2/2016 art. 44.2"}, {"id": "abat31q05", "q": "Los deberes de las personas vecinas sirven, según el art. 44.3, como:", "o": ["Principios para que las ordenanzas tipifiquen infracciones y sanciones", "Requisitos para empadronarse", "Criterios de selección del personal municipal", "Base del cálculo de los tributos"], "e": "Art. 44.3.", "r": "Ley 2/2016 art. 44.3"}, {"id": "abat31q06", "q": "¿En qué municipios es obligatorio aprobar cartas de servicios según la Ley 2/2016?", "o": ["En los de más de 20.000 habitantes", "En todos los municipios", "En los de más de 5.000 habitantes", "En los de más de 50.000 habitantes"], "e": "En el resto es potestativo.", "r": "Ley 2/2016 art. 45"}, {"id": "abat31q07", "q": "¿Qué deben contener las cartas de servicios municipales?", "o": ["Las características del servicio, los derechos y deberes de las personas usuarias y los compromisos de calidad, con indicadores para evaluarlos", "Solo el horario de atención", "La plantilla del personal del servicio", "El presupuesto detallado del servicio"], "e": "Los indicadores se desagregan por sexo, edad u otras variables.", "r": "Ley 2/2016 art. 45"}, {"id": "abat31q08", "q": "¿Por cuál de estas vías se garantiza el gobierno abierto según el art. 47 de la Ley 2/2016?", "o": ["Transparencia, acceso a la información pública, datos abiertos y participación ciudadana", "Elecciones anticipadas", "Referéndum vinculante anual", "Auditorías privadas"], "e": "Su fin es reforzar la calidad institucional y una nueva relación entre gobiernos locales y ciudadanía.", "r": "Ley 2/2016 art. 47"}, {"id": "abat31q09", "q": "Los municipios promueven la calidad de sus servicios mediante:", "o": ["Sistemas de certificación, acreditación o evaluación integrados en las cartas de servicios", "Contratos con empresas privadas obligatoriamente", "Encuestas anuales del Gobierno Vasco", "Inspecciones de la Diputación"], "e": "Art. 46.", "r": "Ley 2/2016 art. 46"}, {"id": "abat31q10", "q": "Comparado con el art. 18 de la LBRL, el catálogo de derechos de la Ley 2/2016:", "o": ["Es más amplio: añade, entre otros, el medio ambiente, la accesibilidad, la información sobre riesgos, la cultura y el euskera", "Es idéntico", "Es más reducido", "Solo recoge derechos electorales"], "e": "También desarrolla mucho más los deberes cívicos.", "r": "Ley 2/2016 art. 43 y LBRL art. 18"}], "incluye": ["getxo-administrativo/t30", "getxo-administrativo/t31"]}, {"id": "t32", "sig": "Tema 32", "titulo": "Tema 32. Ordenanzas, Reglamentos y Bandos de las Entidades Locales. Clases. Procedimiento de elaboración y aprobación. El Reglamento Orgánico", "sub": "Parte Tercera", "preguntas": [{"id": "abat32q01", "q": "¿Qué órgano municipal aprueba las ordenanzas y el reglamento orgánico?", "o": ["El Pleno", "El Alcalde", "La Junta de Gobierno Local", "La Comisión Informativa correspondiente"], "e": "Art. 22.2.d de la LBRL.", "r": "LBRL art. 22.2.d"}, {"id": "abat32q02", "q": "¿Qué órgano municipal dicta los bandos?", "o": ["El Alcalde", "El Pleno", "La Junta de Gobierno Local", "El Secretario"], "e": "Art. 21.1.e de la LBRL.", "r": "LBRL art. 21.1.e"}, {"id": "abat32q03", "q": "La diferencia básica entre una ordenanza y un reglamento municipal es que:", "o": ["La ordenanza regula materias con efectos sobre la ciudadanía y el reglamento, la organización y funcionamiento de la entidad o de sus servicios", "La ordenanza la aprueba el Alcalde y el reglamento el Pleno", "El reglamento tiene rango de ley", "Solo las ordenanzas se publican"], "e": "Las dos son disposiciones generales de rango reglamentario aprobadas por el Pleno.", "r": "Ordenanzas y reglamentos"}, {"id": "abat32q04", "q": "En caso de catástrofe o infortunio público o grave riesgo, el Alcalde puede adoptar las medidas necesarias:", "o": ["Dando cuenta inmediata al Pleno", "Previa autorización del Pleno", "Previa autorización de la Diputación Foral", "Solo si lo acuerda la Junta de Gobierno"], "e": "Es el fundamento de los bandos de necesidad o urgencia (art. 21.1.m LBRL).", "r": "LBRL art. 21.1.m"}, {"id": "abat32q05", "q": "¿Cuál es el primer trámite del procedimiento de aprobación de las ordenanzas del art. 49 de la LBRL?", "o": ["La aprobación inicial por el Pleno", "La publicación en el BOB", "La información pública", "La aprobación definitiva"], "e": "Después: información pública y audiencia, resolución de reclamaciones y aprobación definitiva.", "r": "LBRL art. 49"}, {"id": "abat32q06", "q": "El plazo mínimo de información pública y audiencia a los interesados en la aprobación de una ordenanza es de:", "o": ["Treinta días", "Quince días", "Veinte días", "Diez días"], "e": "Para la presentación de reclamaciones y sugerencias.", "r": "LBRL art. 49.b"}, {"id": "abat32q07", "q": "Si durante la información pública de una ordenanza no se presenta ninguna reclamación ni sugerencia:", "o": ["Se entiende definitivamente adoptado el acuerdo hasta entonces provisional", "Hay que repetir la información pública", "El Alcalde debe aprobarla por decreto", "La ordenanza decae"], "e": "Art. 49 de la LBRL.", "r": "LBRL art. 49"}, {"id": "abat32q08", "q": "¿Dónde se publica el texto íntegro de las ordenanzas municipales en Bizkaia?", "o": ["En el Boletín Oficial de Bizkaia", "En el BOE", "En el BOPV", "Solo en el tablón de anuncios"], "e": "Art. 70.2 de la LBRL.", "r": "LBRL art. 70.2"}, {"id": "abat32q09", "q": "Las ordenanzas entran en vigor cuando se ha publicado completamente su texto y han transcurrido:", "o": ["Quince días hábiles desde la remisión del acuerdo a la Administración del Estado y de la Comunidad Autónoma", "Veinte días naturales", "Un mes", "Tres días"], "e": "Es el plazo del art. 65.2 de la LBRL, al que remite el art. 70.2.", "r": "LBRL arts. 65.2 y 70.2"}, {"id": "abat32q10", "q": "¿Qué mayoría exige la aprobación y modificación del reglamento orgánico del municipio?", "o": ["Mayoría absoluta del número legal de miembros de la corporación", "Mayoría simple", "Dos tercios", "Tres quintos"], "e": "Art. 47.2.f de la LBRL.", "r": "LBRL art. 47.2.f"}, {"id": "abat32q11", "q": "En la organización municipal, el ROF (RD 2568/1986) se aplica respecto del reglamento orgánico:", "o": ["Con carácter supletorio", "Con preferencia", "Nunca", "Solo en municipios de gran población"], "e": "Orden: legislación básica estatal, legislación autonómica, reglamento orgánico y, supletoriamente, el ROF.", "r": "ROF y STC 214/1989"}, {"id": "abat32q12", "q": "¿Cuál de estos principios de buena regulación recoge el art. 129 de la Ley 39/2015?", "o": ["Necesidad, eficacia, proporcionalidad, seguridad jurídica, transparencia y eficiencia", "Jerarquía, competencia y especialidad", "Legalidad, oportunidad y conveniencia", "Unidad, autonomía y suficiencia"], "e": "Art. 129.", "r": "Ley 39/2015 art. 129"}, {"id": "abat32q13", "q": "La consulta pública previa a la elaboración de una norma se hace:", "o": ["A través del portal web, antes de redactar el proyecto", "Después de aprobar la norma", "En el BOE", "Solo si lo piden los grupos de la oposición"], "e": "Art. 133.1 de la Ley 39/2015.", "r": "Ley 39/2015 art. 133.1"}, {"id": "abat32q14", "q": "Contra una ordenanza municipal cabe:", "o": ["Recurso contencioso-administrativo directamente", "Recurso de alzada ante la Diputación", "Recurso de reposición obligatorio", "Reclamación económico-administrativa en todo caso"], "e": "Contra las disposiciones de carácter general no cabe recurso en vía administrativa (art. 112.3 de la Ley 39/2015).", "r": "Ley 39/2015 art. 112.3"}, {"id": "abat32q15", "q": "En defecto de normativa sectorial, las ordenanzas locales pueden tipificar infracciones con multas de hasta:", "o": ["750 euros las leves, 1.500 euros las graves y 3.000 euros las muy graves", "300, 600 y 1.000 euros", "1.000, 2.000 y 5.000 euros", "100, 500 y 1.000 euros"], "e": "Art. 141 de la LBRL.", "r": "LBRL art. 141"}, {"id": "abat32q16", "q": "En un municipio de entre 5.001 y 20.000 habitantes, la iniciativa popular para presentar proyectos de reglamentos requiere las firmas de:", "o": ["El 15 % de los vecinos con derecho de voto", "El 20 %", "El 10 %", "El 5 %"], "e": "En los de hasta 5.000 habitantes, el 20 %; en los de más de 20.000, el 10 %.", "r": "LBRL art. 70 bis"}, {"id": "abat32q17", "q": "¿Qué norma regula en Bizkaia el procedimiento propio de aprobación de las ordenanzas fiscales?", "o": ["La Norma Foral 9/2005, de Haciendas Locales", "La Ley 7/1985 únicamente", "El ROF", "La Ley 2/2016"], "e": "Aprobación provisional, exposición pública durante 30 días y aprobación definitiva.", "r": "NF 9/2005 art. 16"}, {"id": "abat32q18", "q": "El reglamento orgánico municipal NO puede:", "o": ["Suprimir los órganos necesarios del municipio", "Crear comisiones informativas", "Regular los grupos políticos", "Regular la participación ciudadana"], "e": "Puede crear órganos complementarios, pero no suprimir el Alcalde, los Tenientes de Alcalde, el Pleno o la Junta de Gobierno cuando sea obligatoria.", "r": "LBRL art. 20"}]}, {"id": "t33", "sig": "Tema 33", "titulo": "Tema 33. ROF (RD 2568/1986) (I): Título Preliminar y organización necesaria del Municipio (Título II, Cap. I)", "sub": "Parte Tercera", "preguntas": [{"id": "abat33q01", "q": "¿Qué norma aprueba el Reglamento de Organización, Funcionamiento y Régimen Jurídico de las Entidades Locales (ROF)?", "o": ["El Real Decreto 2568/1986, de 28 de noviembre", "El Real Decreto 1690/1986", "El Real Decreto 1372/1986", "La Ley 7/1985"], "e": "El RD 1690/1986 es el Reglamento de Población; el RD 1372/1986, el de Bienes.", "r": "ROF"}, {"id": "abat33q02", "q": "¿Cómo se llama hoy la antigua «Comisión de Gobierno» del ROF?", "o": ["Junta de Gobierno Local", "Comisión Informativa", "Junta de Portavoces", "Comisión Especial de Cuentas"], "e": "Cambió de nombre con la Ley 57/2003.", "r": "ROF arts. 52-53"}, {"id": "abat33q03", "q": "¿Cuál de estos es un órgano necesario del Ayuntamiento según el art. 35 del ROF?", "o": ["Los Tenientes de Alcalde", "Las Comisiones informativas especiales", "Los Consejos sectoriales", "Las Juntas Municipales de Distrito"], "e": "Órganos necesarios: Alcalde, Tenientes de Alcalde, Pleno y Junta de Gobierno (en municipios de más de 5.000 habitantes o si lo decide el municipio).", "r": "ROF art. 35"}, {"id": "abat33q04", "q": "La Junta de Gobierno Local es obligatoria en los municipios de:", "o": ["Más de 5.000 habitantes, y en los de menos si lo dispone su reglamento orgánico o lo acuerda el Pleno", "Más de 20.000 habitantes", "Todos los municipios", "Más de 50.000 habitantes"], "e": "Art. 20.1.b de la LBRL.", "r": "LBRL art. 20.1.b"}, {"id": "abat33q05", "q": "¿Qué día se constituyen las corporaciones municipales en sesión pública?", "o": ["El vigésimo día posterior a la celebración de las elecciones, salvo recurso contencioso-electoral", "El décimo día posterior", "El trigésimo día posterior", "El día siguiente a la proclamación de electos"], "e": "Si hay recurso contencioso-electoral, el cuadragésimo día.", "r": "ROF art. 37.1"}, {"id": "abat33q06", "q": "En la sesión constitutiva, la Mesa de Edad está integrada por:", "o": ["Los concejales electos de mayor y menor edad presentes, actuando de secretario el de la corporación", "El Alcalde saliente y el Secretario", "Los cabezas de lista de los dos partidos más votados", "El concejal de mayor edad solamente"], "e": "Art. 37.2.", "r": "ROF art. 37.2"}, {"id": "abat33q07", "q": "Si en la sesión constitutiva no concurre la mayoría absoluta de los concejales electos:", "o": ["Se celebra sesión dos días después y queda constituida la corporación cualquiera que sea el número de concejales presentes", "Se repiten las elecciones", "La Diputación nombra una comisión gestora", "Se aplaza un mes"], "e": "Art. 37.4.", "r": "ROF art. 37.4"}, {"id": "abat33q08", "q": "Dentro de los treinta días siguientes a la sesión constitutiva, el Alcalde convoca un Pleno extraordinario para, entre otras cosas:", "o": ["Fijar la periodicidad de las sesiones plenarias y crear y componer las comisiones informativas", "Aprobar los presupuestos", "Elegir al Alcalde", "Aprobar el reglamento orgánico"], "e": "Y para conocer los nombramientos de Tenientes de Alcalde y las delegaciones del Alcalde.", "r": "ROF art. 38"}, {"id": "abat33q09", "q": "Al terminar su mandato de cuatro años, los concejales cesantes:", "o": ["Continúan en funciones solo para la administración ordinaria hasta la toma de posesión de sus sucesores", "Cesan inmediatamente sin ninguna función", "Pueden adoptar cualquier acuerdo", "Siguen en el cargo con plenas facultades"], "e": "No pueden adoptar acuerdos que requieran mayoría cualificada.", "r": "ROF art. 39"}, {"id": "abat33q10", "q": "Si el Alcalde electo no está presente en la sesión constitutiva, se le requiere para que tome posesión ante el Pleno en el plazo de:", "o": ["Cuarenta y ocho horas", "Diez días", "Tres días", "Una semana"], "e": "Art. 40.", "r": "ROF art. 40"}, {"id": "abat33q11", "q": "¿En qué momento da cuenta el Alcalde al Pleno de las resoluciones que ha adoptado?", "o": ["En cada sesión plenaria ordinaria, de forma sucinta, desde la última sesión", "Una vez al año", "Solo si lo pide la oposición", "Al final del mandato"], "e": "Para que los concejales conozcan su desarrollo y ejerzan el control (art. 42).", "r": "ROF art. 42"}, {"id": "abat33q12", "q": "Las delegaciones genéricas del Alcalde pueden conferirse a favor de:", "o": ["La Junta de Gobierno o de los Tenientes de Alcalde o concejales miembros de la Junta", "Cualquier vecino del municipio", "El Secretario de la corporación", "Cualquier concejal, aunque no sea de la Junta, para áreas completas"], "e": "Las especiales, para un asunto, servicio o barrio concreto, pueden hacerse en cualquier concejal.", "r": "ROF art. 43"}, {"id": "abat33q13", "q": "La delegación de atribuciones del Alcalde surte efecto:", "o": ["Desde el día siguiente al de la fecha del decreto, salvo que este disponga otra cosa, sin perjuicio de su publicación en el BOB", "Desde su publicación en el BOB", "Desde que el Pleno la ratifica", "Desde el mismo día de su firma, sin necesidad de publicación"], "e": "Se da cuenta al Pleno en la primera sesión que celebre.", "r": "ROF art. 44.2"}, {"id": "abat33q14", "q": "¿Cuál de estas atribuciones del Alcalde es indelegable?", "o": ["Convocar y presidir las sesiones del Pleno y de la Junta de Gobierno y decidir los empates con voto de calidad", "La dirección de un área de servicios", "La concesión de licencias de obras menores", "La gestión de un barrio"], "e": "Art. 21.3 de la LBRL.", "r": "LBRL art. 21.3"}, {"id": "abat33q15", "q": "Los Tenientes de Alcalde son nombrados y cesados libremente por:", "o": ["El Alcalde, entre los miembros de la Junta de Gobierno", "El Pleno, por mayoría absoluta", "La Junta de Gobierno", "Los grupos políticos"], "e": "Donde no exista Junta de Gobierno, entre los concejales.", "r": "ROF art. 46"}, {"id": "abat33q16", "q": "Donde no existe Junta de Gobierno, el número de Tenientes de Alcalde no puede exceder de:", "o": ["Un tercio del número legal de miembros de la corporación", "La mitad de los concejales", "Tres", "Cinco"], "e": "Donde existe, no puede exceder del número de miembros de la Junta.", "r": "ROF art. 46"}, {"id": "abat33q17", "q": "Los Tenientes de Alcalde sustituyen al Alcalde:", "o": ["Por el orden de su nombramiento, en los casos de vacante, ausencia o enfermedad", "Por orden de edad", "Por sorteo", "Según decida el Pleno en cada caso"], "e": "Si el Alcalde se ausenta más de 24 horas sin delegar, le sustituye el Teniente de Alcalde que corresponda.", "r": "ROF art. 47"}, {"id": "abat33q18", "q": "Quien sustituye al Alcalde en sus funciones:", "o": ["No puede revocar las delegaciones que el Alcalde haya otorgado", "Puede revocar libremente las delegaciones", "Asume la condición de Alcalde", "Debe ser ratificado por el Pleno"], "e": "Art. 48.", "r": "ROF art. 48"}, {"id": "abat33q19", "q": "El Pleno puede delegar atribuciones en el Alcalde o en la Junta de Gobierno mediante acuerdo adoptado por:", "o": ["Mayoría simple, salvo las materias indelegables del art. 22.4 de la LBRL", "Mayoría absoluta en todo caso", "Unanimidad", "Dos tercios"], "e": "No puede delegar, entre otras, la aprobación del reglamento orgánico, las ordenanzas o los presupuestos.", "r": "ROF art. 51 y LBRL art. 22.4"}, {"id": "abat33q20", "q": "La Junta de Gobierno Local está formada por el Alcalde y un número de concejales no superior a:", "o": ["Un tercio del número legal de miembros de la corporación", "La mitad", "Cinco", "Dos tercios"], "e": "Los nombra y separa libremente el Alcalde, dando cuenta al Pleno.", "r": "ROF art. 52"}, {"id": "abat33q21", "q": "¿Cuál es la función principal de la Junta de Gobierno Local según el art. 53 del ROF?", "o": ["La asistencia permanente al Alcalde en el ejercicio de sus atribuciones", "Aprobar las ordenanzas", "Controlar al Alcalde", "Aprobar los presupuestos"], "e": "Además, ejerce las atribuciones que le deleguen el Alcalde o el Pleno y las que le asignen las leyes.", "r": "ROF art. 53"}, {"id": "abat33q22", "q": "Las sesiones de la Junta de Gobierno Local:", "o": ["No son públicas", "Son siempre públicas", "Se retransmiten obligatoriamente", "Son públicas si lo pide un vecino"], "e": "Art. 70.1 de la LBRL.", "r": "LBRL art. 70.1"}, {"id": "abat33q23", "q": "En el régimen de concejo abierto, el gobierno municipal corresponde a:", "o": ["El Alcalde y la Asamblea vecinal formada por todos los electores", "El Pleno y el Alcalde", "La Diputación Foral", "La Junta de Gobierno"], "e": "Art. 54 del ROF y art. 29 de la LBRL.", "r": "ROF art. 54"}]}, {"id": "t34", "sig": "Tema 34", "titulo": "Tema 34. ROF (II): órganos complementarios. Composición, atribuciones y funcionamiento (Título IV)", "sub": "Parte Tercera", "preguntas": [{"id": "abat34q01", "q": "¿Cuál de estos órganos complementarios existe solo en los municipios, según el art. 119 del ROF?", "o": ["Las Juntas Municipales de Distrito", "Las Comisiones informativas", "La Comisión Especial de Cuentas", "Los Consejos sectoriales"], "e": "También solo en municipios: los representantes personales del Alcalde en poblados y barriadas.", "r": "ROF art. 119"}, {"id": "abat34q02", "q": "¿Cuál de estas es una causa de pérdida de la condición de concejal delegado?", "o": ["La revocación de la delegación por el Alcalde, con las mismas formalidades que para otorgarla", "El cambio de grupo político", "La celebración de un Pleno extraordinario", "La aprobación de los presupuestos"], "e": "También la renuncia expresa por escrito y la pérdida de la condición de miembro de la Junta de Gobierno o de Teniente de Alcalde.", "r": "ROF art. 120"}, {"id": "abat34q03", "q": "Si una delegación se refiere genéricamente a una materia sin concretar potestades, se entiende que comprende:", "o": ["Todas las facultades, derechos y deberes del órgano delegante referidos a la materia, salvo las indelegables", "Solo la facultad de informar", "Solo la gestión, sin capacidad de resolver", "Nada; la delegación es nula"], "e": "Art. 121.", "r": "ROF art. 121"}, {"id": "abat34q04", "q": "Los representantes personales del Alcalde en poblados y barriadas:", "o": ["Los nombra el Alcalde entre los vecinos residentes, y su mandato dura lo que el del Alcalde que los nombró", "Los elige el Pleno por mayoría absoluta", "Los eligen los vecinos del barrio", "Son funcionarios de carrera"], "e": "Tienen carácter de autoridad en el cumplimiento de sus cometidos municipales.", "r": "ROF art. 122"}, {"id": "abat34q05", "q": "Las Comisiones informativas son órganos:", "o": ["Sin atribuciones resolutorias, que estudian, informan o consultan los asuntos que se someten al Pleno", "Con capacidad para aprobar ordenanzas", "Formados por vecinos y concejales", "Que sustituyen a la Junta de Gobierno"], "e": "Están integradas exclusivamente por miembros de la corporación.", "r": "ROF art. 123"}, {"id": "abat34q06", "q": "Las Comisiones informativas son obligatorias en los municipios de:", "o": ["Más de 5.000 habitantes", "Más de 20.000 habitantes", "Todos los municipios", "Más de 50.000 habitantes"], "e": "Art. 20.1.c de la LBRL. Todos los grupos políticos tienen derecho a participar en ellas.", "r": "LBRL art. 20.1.c"}, {"id": "abat34q07", "q": "Las Comisiones informativas especiales:", "o": ["Se constituyen para un asunto concreto y se extinguen al dictaminarlo, salvo que el acuerdo diga otra cosa", "Duran todo el mandato", "Se ocupan de todas las materias del Pleno", "Las crea el Alcalde por decreto"], "e": "Las permanentes se reparten las materias del Pleno por áreas y duran todo el mandato.", "r": "ROF art. 124"}, {"id": "abat34q08", "q": "¿Quién es el Presidente nato de todas las Comisiones informativas?", "o": ["El Alcalde, que puede delegar la presidencia efectiva en cualquier miembro de la corporación", "El concejal de más edad", "El portavoz del grupo mayoritario", "El Secretario de la corporación"], "e": "A propuesta de la propia Comisión, tras elección en su seno.", "r": "ROF art. 125.a"}, {"id": "abat34q09", "q": "La composición de las Comisiones informativas es:", "o": ["Proporcional a la representatividad de los distintos grupos políticos", "Igual para todos los grupos", "Solo con concejales del gobierno", "Decidida libremente por el Alcalde"], "e": "La adscripción de cada concejal la comunica el portavoz del grupo al Alcalde.", "r": "ROF art. 125.b y c"}, {"id": "abat34q10", "q": "Los dictámenes de las Comisiones informativas son:", "o": ["Preceptivos y no vinculantes", "Facultativos y vinculantes", "Preceptivos y vinculantes", "Facultativos y no vinculantes"], "e": "En caso de urgencia, el Pleno puede decidir sin dictamen, dando cuenta después a la Comisión.", "r": "ROF art. 126"}, {"id": "abat34q11", "q": "La Comisión Especial de Cuentas es de existencia preceptiva:", "o": ["En todos los municipios, sea cual sea su población", "Solo en los de más de 5.000 habitantes", "Solo en los de gran población", "Solo si lo acuerda el Pleno"], "e": "Art. 116 de la LBRL y art. 127 del ROF.", "r": "ROF art. 127"}, {"id": "abat34q12", "q": "¿Cuál es la función de la Comisión Especial de Cuentas?", "o": ["El examen, estudio e informe de todas las cuentas presupuestarias y extrapresupuestarias que deba aprobar el Pleno", "Elaborar el presupuesto municipal", "Fiscalizar a los contratistas", "Recaudar los tributos"], "e": "Sobre todo, la Cuenta General.", "r": "ROF art. 127"}, {"id": "abat34q13", "q": "Las Juntas Municipales de Distrito son:", "o": ["Órganos territoriales de gestión desconcentrada que crea el Pleno para mejorar la gestión y facilitar la participación", "Entidades locales menores con personalidad jurídica", "Asociaciones vecinales", "Órganos de la Diputación Foral"], "e": "Su reglamento forma parte integrante del Reglamento Orgánico.", "r": "ROF arts. 128 y 129"}, {"id": "abat34q14", "q": "Los Consejos sectoriales desarrollan exclusivamente funciones de:", "o": ["Informe y, en su caso, propuesta", "Resolución", "Gestión de servicios", "Control del Alcalde"], "e": "Canalizan la participación de los ciudadanos y sus asociaciones en un sector (cultura, deporte, igualdad…).", "r": "ROF art. 130"}, {"id": "abat34q15", "q": "¿Quién preside los Consejos sectoriales?", "o": ["Un miembro de la corporación nombrado y separado libremente por el Alcalde", "Un representante elegido por las asociaciones", "El Alcalde obligatoriamente", "El técnico municipal del área"], "e": "Hace de enlace entre el Consejo y la corporación.", "r": "ROF art. 131"}, {"id": "abat34q16", "q": "Las Comisiones informativas se convocan, salvo urgencia, con una antelación de:", "o": ["Dos días hábiles, acompañando el orden del día", "Cinco días", "24 horas", "Una semana"], "e": "Art. 134.", "r": "ROF art. 134"}, {"id": "abat34q17", "q": "El presidente de una Comisión informativa debe convocar sesión extraordinaria cuando lo solicite:", "o": ["Al menos la cuarta parte de sus miembros", "La mitad de sus miembros", "Un solo miembro", "El Pleno"], "e": "Art. 134.", "r": "ROF art. 134"}, {"id": "abat34q18", "q": "En segunda convocatoria, una hora después, para constituir válidamente una Comisión informativa se requiere la presencia de:", "o": ["Un mínimo de tres miembros", "La mayoría absoluta", "Todos los miembros", "Dos miembros"], "e": "En primera convocatoria se exige la mayoría absoluta de sus componentes.", "r": "ROF art. 135"}, {"id": "abat34q19", "q": "Los dictámenes de las Comisiones informativas se aprueban por:", "o": ["Mayoría simple de los presentes, decidiendo los empates el presidente con voto de calidad", "Mayoría absoluta", "Unanimidad", "Mayoría de dos tercios"], "e": "Los disidentes pueden formular voto particular para defenderlo en el Pleno.", "r": "ROF arts. 135 y 137"}, {"id": "abat34q20", "q": "¿En qué Comisión informativa asiste siempre el interventor?", "o": ["En la Comisión de Hacienda", "En la de Urbanismo", "En la de Cultura", "En ninguna"], "e": "El presidente puede requerir la presencia de personal o miembros de la corporación.", "r": "ROF art. 137"}]}, {"id": "t35", "sig": "Tema 35", "titulo": "Tema 35. Reglamento de Bienes (RD 1372/1986) (I): concepto y clasificación de los bienes; el patrimonio de las entidades locales", "sub": "Parte Tercera", "preguntas": [{"id": "abat35q01", "q": "¿Qué norma aprueba el Reglamento de Bienes de las Entidades Locales?", "o": ["El Real Decreto 1372/1986, de 13 de junio", "El Real Decreto 2568/1986", "El Real Decreto 1690/1986", "La Ley 33/2003"], "e": "La Ley 33/2003 (LPAP) tiene preceptos básicos que también se aplican a los entes locales.", "r": "RB"}, {"id": "abat35q02", "q": "Según el art. 1 del RB, el patrimonio de las entidades locales está constituido por:", "o": ["El conjunto de bienes, derechos y acciones que les pertenezcan", "Solo los bienes inmuebles", "Los bienes de dominio público", "Los bienes inscritos en el Registro de la Propiedad"], "e": "Art. 1.", "r": "RB art. 1"}, {"id": "abat35q03", "q": "¿En qué dos grandes clases se clasifican los bienes de las entidades locales?", "o": ["Bienes de dominio público y bienes patrimoniales", "Bienes muebles e inmuebles", "Bienes comunales y de propios", "Bienes rústicos y urbanos"], "e": "Art. 2. Los comunales son una modalidad de dominio público.", "r": "RB art. 2"}, {"id": "abat35q04", "q": "Las plazas, calles, parques y fuentes de un municipio son bienes:", "o": ["De dominio público de uso público", "De dominio público de servicio público", "Patrimoniales", "Comunales"], "e": "Art. 3: los que todos pueden usar.", "r": "RB art. 3"}, {"id": "abat35q05", "q": "La casa consistorial, los mercados, los museos y los cementerios son bienes:", "o": ["De dominio público de servicio público", "De dominio público de uso público", "Patrimoniales", "Comunales"], "e": "Art. 4: destinados directamente al cumplimiento de fines públicos.", "r": "RB art. 4"}, {"id": "abat35q06", "q": "Los bienes comunales:", "o": ["Son de dominio público y su aprovechamiento corresponde al común de los vecinos", "Son patrimoniales", "Pueden pertenecer a la Diputación Foral", "Pueden venderse libremente"], "e": "Solo pueden pertenecer a los municipios y a las entidades locales menores.", "r": "RB art. 2.3"}, {"id": "abat35q07", "q": "¿Cuál de estos es un bien patrimonial o de propios?", "o": ["Una vivienda propiedad del ayuntamiento que está alquilada", "Un parque público", "La biblioteca municipal", "Un monte comunal"], "e": "Art. 6: no destinados a uso ni servicio público y pueden ser fuente de ingresos.", "r": "RB art. 6"}, {"id": "abat35q08", "q": "Los bienes patrimoniales se rigen por su legislación específica y, en su defecto, por:", "o": ["Las normas de Derecho privado", "La Ley 39/2015", "El Código Penal", "El ROF"], "e": "Art. 6.2.", "r": "RB art. 6"}, {"id": "abat35q09", "q": "Los bienes de dominio público y comunales son:", "o": ["Inalienables, inembargables e imprescriptibles, y no están sujetos a tributo alguno", "Alienables e inembargables", "Embargables pero imprescriptibles", "Prescriptibles a los 30 años"], "e": "Art. 5 RB, art. 80 LBRL y art. 132 CE.", "r": "RB art. 5"}, {"id": "abat35q10", "q": "Las porciones de terreno de la entidad local que, por su reducida extensión, forma irregular o emplazamiento, no son susceptibles de uso adecuado se llaman:", "o": ["Parcelas sobrantes", "Efectos no utilizables", "Bienes comunales", "Bienes revertibles"], "e": "Son patrimoniales y se venden directamente al colindante (art. 115).", "r": "RB art. 7"}, {"id": "abat35q11", "q": "Los bienes muebles que, por su deterioro o depreciación, resultan inaplicables a los servicios se denominan:", "o": ["Efectos no utilizables", "Parcelas sobrantes", "Bienes semovientes", "Bienes revertibles"], "e": "Art. 7.", "r": "RB art. 7"}, {"id": "abat35q12", "q": "La alteración de la calificación jurídica de un bien exige un expediente con información pública durante:", "o": ["Un mes", "Quince días", "Veinte días", "Dos meses"], "e": "Y acuerdo del Pleno por mayoría absoluta.", "r": "RB art. 8"}, {"id": "abat35q13", "q": "¿Qué mayoría exige el acuerdo de alteración de la calificación jurídica de los bienes demaniales?", "o": ["Mayoría absoluta del número legal de miembros", "Mayoría simple", "Dos tercios", "Unanimidad"], "e": "Art. 47.2.n de la LBRL.", "r": "LBRL art. 47.2.n"}, {"id": "abat35q14", "q": "Un bien desafectado se incorpora al patrimonio de la entidad:", "o": ["Cuando se produce la recepción formal por el órgano competente", "En el momento del acuerdo del Pleno", "Al publicarse en el BOB", "Al inscribirse en el inventario"], "e": "Mientras tanto sigue siendo de dominio público (art. 8.3).", "r": "RB art. 8.3"}, {"id": "abat35q15", "q": "¿Cuál de estos supuestos produce la alteración automática de la calificación jurídica, sin expediente?", "o": ["La adscripción de bienes patrimoniales durante más de 25 años a un uso o servicio público", "La adscripción durante más de 5 años", "La decisión del Alcalde", "La inscripción en el Registro de la Propiedad"], "e": "También la aprobación definitiva de planes urbanísticos y proyectos de obras, y la usucapión.", "r": "RB art. 8.4"}, {"id": "abat35q16", "q": "Si la entidad local no ejerce las acciones para defender sus bienes, cualquier vecino:", "o": ["Puede requerirle que lo haga y, si no lo hace, ejercerlas en nombre de la entidad", "No puede hacer nada", "Debe acudir al Ararteko", "Puede apropiarse del bien"], "e": "Acción vecinal del art. 68 de la LBRL.", "r": "RB art. 9 y LBRL art. 68"}, {"id": "abat35q17", "q": "Las herencias que recibe una entidad local se aceptan:", "o": ["Siempre a beneficio de inventario", "Pura y simplemente", "Solo si lo autoriza la Diputación", "Solo si no tienen cargas"], "e": "Art. 12.", "r": "RB art. 12"}, {"id": "abat35q18", "q": "Si un bien se adquiere con la condición de destinarlo a un fin, la condición se entiende cumplida si ha servido a ese fin durante:", "o": ["Treinta años", "Diez años", "Veinticinco años", "Cincuenta años"], "e": "Aunque después deje de hacerlo por razones de interés público.", "r": "RB art. 13"}, {"id": "abat35q19", "q": "¿Pueden los particulares adquirir por prescripción bienes de las entidades locales?", "o": ["Solo los patrimoniales, nunca los de dominio público", "Sí, cualquier bien", "No, ninguno", "Solo los comunales"], "e": "Art. 14.", "r": "RB art. 14"}, {"id": "abat35q20", "q": "¿Cuál de estos NO es un modo de adquirir bienes según el art. 10 del RB?", "o": ["La confiscación", "La herencia, legado o donación", "La prescripción", "La ocupación"], "e": "También por atribución de la ley y a título oneroso.", "r": "RB art. 10"}]}, {"id": "t36", "sig": "Tema 36", "titulo": "Tema 36. Reglamento de Bienes (II): conservación y tutela; disfrute y aprovechamiento; enajenación", "sub": "Parte Tercera", "preguntas": [{"id": "abat36q01", "q": "Las corporaciones locales están obligadas a formar inventario:", "o": ["De todos sus bienes y derechos, cualquiera que sea su naturaleza o forma de adquisición", "Solo de los bienes inmuebles", "Solo de los bienes patrimoniales", "Solo de los bienes de valor superior a 3.000 euros"], "e": "Art. 17.", "r": "RB art. 17"}, {"id": "abat36q02", "q": "¿Cuántos epígrafes tiene el inventario de bienes según el art. 18 del RB?", "o": ["Ocho", "Cinco", "Seis", "Diez"], "e": "Inmuebles; derechos reales; muebles históricos o valiosos; valores mobiliarios y créditos; vehículos; semovientes; otros muebles; bienes revertibles.", "r": "RB art. 18"}, {"id": "abat36q03", "q": "En el inventario, los animales se recogen en el epígrafe de:", "o": ["Semovientes", "Muebles no comprendidos en otros epígrafes", "Bienes revertibles", "Derechos reales"], "e": "Art. 18.", "r": "RB art. 18"}, {"id": "abat36q04", "q": "¿Qué órgano aprueba el inventario, su rectificación y su comprobación?", "o": ["El Pleno", "El Alcalde", "El Secretario", "La Junta de Gobierno Local"], "e": "Art. 34.", "r": "RB art. 34"}, {"id": "abat36q05", "q": "La rectificación del inventario se hace:", "o": ["Anualmente, y se comprueba siempre que se renueve la corporación", "Cada cuatro años", "Cada dos años", "Solo cuando hay altas o bajas"], "e": "Art. 33.", "r": "RB art. 33"}, {"id": "abat36q06", "q": "Para inscribir sus bienes en el Registro de la Propiedad, a las entidades locales les basta:", "o": ["Una certificación del Secretario con el visto bueno del Presidente", "Una escritura notarial", "Una sentencia judicial", "Una resolución de la Diputación"], "e": "Los honorarios de los registradores se reducen a la mitad (art. 36).", "r": "RB art. 36"}, {"id": "abat36q07", "q": "¿Cuál de estas potestades tienen las entidades locales para defender su patrimonio?", "o": ["Investigación, deslinde, recuperación de oficio y desahucio administrativo", "Expropiación de bienes de otras Administraciones", "Embargo de bienes de dominio público estatal", "Usucapión de bienes de particulares por decreto"], "e": "Art. 44.", "r": "RB art. 44"}, {"id": "abat36q08", "q": "En la potestad de investigación, el particular que denuncia un bien tiene como premio:", "o": ["El 10 % del valor líquido obtenido en la venta o de la tasación", "El 5 %", "El 25 %", "Nada"], "e": "Arts. 45-55.", "r": "RB arts. 45-55"}, {"id": "abat36q09", "q": "El deslinde de un bien se anuncia con una antelación de:", "o": ["Sesenta días", "Treinta días", "Quince días", "Diez días"], "e": "El apeo fija los linderos con un técnico y acta del Secretario.", "r": "RB arts. 56-69"}, {"id": "abat36q10", "q": "Las entidades locales pueden recuperar por sí la posesión de los bienes de dominio público usurpados:", "o": ["En cualquier tiempo", "En el plazo de un año", "En el plazo de cinco años", "Solo con sentencia judicial"], "e": "Los patrimoniales, en el plazo de un año desde la usurpación (art. 70).", "r": "RB art. 70"}, {"id": "abat36q11", "q": "La recuperación de oficio de bienes patrimoniales debe hacerse en el plazo de:", "o": ["Un año desde el día siguiente a la usurpación", "En cualquier tiempo", "Seis meses", "Cinco años"], "e": "Pasado ese plazo, hay que acudir a los tribunales civiles.", "r": "RB art. 70"}, {"id": "abat36q12", "q": "Las corporaciones locales, ante demandas judiciales sobre el dominio de sus bienes:", "o": ["No pueden allanarse", "Pueden allanarse si lo acuerda el Alcalde", "Deben allanarse siempre", "Pueden allanarse por mayoría simple del Pleno"], "e": "Art. 73.", "r": "RB art. 73"}, {"id": "abat36q13", "q": "Pasear por la calle es un ejemplo de uso:", "o": ["Común general", "Común especial", "Privativo", "Anormal"], "e": "Se ejerce libremente, sin título (art. 76).", "r": "RB arts. 75 y 76"}, {"id": "abat36q14", "q": "El uso común especial del dominio público (por ejemplo, un vado o una terraza) requiere:", "o": ["Licencia", "Concesión administrativa", "Ningún título", "Contrato de arrendamiento"], "e": "Art. 77.", "r": "RB art. 77"}, {"id": "abat36q15", "q": "El uso privativo del dominio público (por ejemplo, un quiosco fijo) requiere:", "o": ["Concesión administrativa", "Licencia", "Ningún título", "Autorización verbal del Alcalde"], "e": "Art. 78. El uso anormal también necesita concesión.", "r": "RB art. 78"}, {"id": "abat36q16", "q": "¿Cuál es hoy el plazo máximo de una concesión demanial, según la Ley 33/2003?", "o": ["75 años", "99 años", "50 años", "Tiempo indefinido"], "e": "El RB decía 99 años; el art. 93.3 de la LPAP, básico, lo rebaja a 75. Nunca por tiempo indefinido.", "r": "RB art. 79 y LPAP art. 93.3"}, {"id": "abat36q17", "q": "El canon de una concesión de dominio público tiene naturaleza de:", "o": ["Tasa", "Precio privado", "Impuesto", "Contribución especial"], "e": "Art. 80.", "r": "RB art. 80"}, {"id": "abat36q18", "q": "En los arrendamientos de bienes patrimoniales, el canon mínimo es:", "o": ["El 6 % del valor en venta del bien", "El 3 %", "El 10 %", "El 1 %"], "e": "Subasta obligatoria si la duración supera 5 años o el precio el 5 % de los recursos ordinarios.", "r": "RB art. 92"}, {"id": "abat36q19", "q": "¿Cuál es la forma preferente de aprovechamiento de los bienes comunales?", "o": ["La explotación común o cultivo colectivo", "La adjudicación por precio", "El arrendamiento a empresas", "La venta"], "e": "Después, el aprovechamiento según costumbre o por lotes, y en último lugar la adjudicación por precio.", "r": "RB art. 94"}, {"id": "abat36q20", "q": "Los bienes comunales pueden desafectarse si no han sido objeto de disfrute comunal durante más de:", "o": ["Diez años", "Cinco años", "Veinticinco años", "Treinta años"], "e": "Con información pública, mayoría absoluta y aprobación autonómica.", "r": "RB art. 100"}, {"id": "abat36q21", "q": "¿Qué bienes de las entidades locales pueden enajenarse?", "o": ["Solo los patrimoniales", "Todos", "Solo los comunales", "Los de dominio público, con autorización autonómica"], "e": "El dominio público es inalienable: primero hay que desafectarlo.", "r": "RB arts. 109-119"}, {"id": "abat36q22", "q": "Los inmuebles patrimoniales necesitan autorización autonómica para enajenarse cuando su valor excede del:", "o": ["25 % de los recursos ordinarios del presupuesto", "10 %", "5 %", "50 %"], "e": "En los demás casos, se da cuenta a la Comunidad Autónoma.", "r": "RB art. 109.1"}, {"id": "abat36q23", "q": "La cesión gratuita de bienes patrimoniales exige acuerdo por:", "o": ["Mayoría absoluta", "Mayoría simple", "Unanimidad", "Decreto de Alcaldía"], "e": "Solo a entidades públicas o instituciones privadas de interés público sin ánimo de lucro.", "r": "RB arts. 109.2-111"}, {"id": "abat36q24", "q": "Salvo pacto, el bien cedido gratuitamente debe destinarse al fin previsto en un plazo de:", "o": ["Cinco años, y mantenerse en ese destino durante los treinta años siguientes", "Un año, y mantenerse diez años", "Diez años, y mantenerse cincuenta años", "Dos años, y mantenerse veinte años"], "e": "Si no, revierte con sus mejoras (art. 111).", "r": "RB art. 111"}, {"id": "abat36q25", "q": "La permuta de bienes sin licitación es posible si la diferencia de valor entre los bienes no supera el:", "o": ["40 % del que lo tenga mayor", "10 %", "25 %", "50 %"], "e": "Y si se acredita su necesidad.", "r": "RB art. 112"}, {"id": "abat36q26", "q": "Las parcelas sobrantes se enajenan:", "o": ["Por venta directa a los propietarios colindantes o se permutan", "Por subasta pública obligatoria", "Por cesión gratuita a cualquier vecino", "No pueden enajenarse"], "e": "Art. 115.", "r": "RB art. 115"}, {"id": "abat36q27", "q": "Hoy, según la LBRL, la enajenación de bienes requiere mayoría absoluta cuando su cuantía excede del:", "o": ["20 % de los recursos ordinarios del presupuesto", "10 %", "5 %", "25 %"], "e": "El RB decía 10 %; el art. 47.2.m de la LBRL fija el 20 %.", "r": "LBRL art. 47.2.m"}]}, {"id": "t37", "sig": "Tema 37", "titulo": "Tema 37. Norma Foral 9/2005, de Haciendas Locales de Bizkaia: ámbito de aplicación y recursos de las haciendas locales", "sub": "Parte Tercera", "preguntas": [], "incluye": ["getxo-administrativo/t39"]}, {"id": "t38", "sig": "Tema 38", "titulo": "Tema 38. IBI e IIVTNU: naturaleza, hecho imponible y sujeto pasivo", "sub": "Parte Tercera", "preguntas": [{"id": "abat38q01", "q": "¿Qué Norma Foral regula el IBI en Bizkaia?", "o": ["La Norma Foral 4/2016, de 18 de mayo", "La Norma Foral 8/1989", "La Norma Foral 9/2005", "La Norma Foral 6/1989"], "e": "Efectos desde el 1-1-2017. Los conceptos catastrales están en la NF 3/2016.", "r": "NF 4/2016"}, {"id": "abat38q02", "q": "El IBI es un tributo:", "o": ["Directo, de carácter real y obligatorio", "Indirecto y potestativo", "Directo, personal y potestativo", "Indirecto y obligatorio"], "e": "Grava el valor de los bienes inmuebles.", "r": "NF 4/2016 art. 1"}, {"id": "abat38q03", "q": "¿Cuál es el orden de prelación del hecho imponible del IBI?", "o": ["Concesión administrativa, derecho de superficie, derecho de usufructo y derecho de propiedad", "Propiedad, usufructo, superficie y concesión", "Usufructo, propiedad, concesión y superficie", "Propiedad, concesión, superficie y usufructo"], "e": "Se aplica el primero que concurra (art. 2.2).", "r": "NF 4/2016 art. 2"}, {"id": "abat38q04", "q": "Si un inmueble tiene nudo propietario y usufructuario, ¿quién paga el IBI?", "o": ["El usufructuario", "El nudo propietario", "Los dos a partes iguales", "El ayuntamiento"], "e": "El usufructo va antes que la propiedad en el orden de prelación.", "r": "NF 4/2016 art. 2.2"}, {"id": "abat38q05", "q": "¿Cuál de estos es un bien inmueble de características especiales (BICE)?", "o": ["Una autopista de peaje", "Un piso en suelo urbano", "Una granja en suelo rústico", "Un local comercial"], "e": "También centrales energéticas, presas, aeropuertos y puertos comerciales.", "r": "NF 3/2016 art. 9"}, {"id": "abat38q06", "q": "¿Cuál de estos inmuebles NO está sujeto al IBI?", "o": ["Un parque municipal de uso público, propiedad del propio municipio", "Una vivienda municipal alquilada a un particular", "Un local comercial privado", "Un piso propiedad de una empresa"], "e": "Los bienes municipales cedidos a terceros con contraprestación sí están sujetos.", "r": "NF 4/2016 art. 2.5"}, {"id": "abat38q07", "q": "Las carreteras y caminos de aprovechamiento público y gratuito:", "o": ["No están sujetos al IBI", "Están exentos del IBI", "Pagan IBI rústico", "Pagan IBI como BICE"], "e": "Art. 2.5.a. No confundir no sujeción con exención.", "r": "NF 4/2016 art. 2.5"}, {"id": "abat38q08", "q": "¿Qué particularidad foral recoge el sujeto pasivo del IBI en Bizkaia?", "o": ["Incluye las herencias pendientes del ejercicio de un poder testatorio", "Excluye a las personas jurídicas", "Solo incluye a los residentes en Bizkaia", "Excluye a las comunidades de bienes"], "e": "Art. 4.", "r": "NF 4/2016 art. 4"}, {"id": "abat38q09", "q": "Si cambia el titular de un inmueble con deudas de IBI:", "o": ["El inmueble queda afecto al pago de la totalidad de la cuota", "La deuda se extingue", "Solo responde el antiguo titular", "La deuda la asume el ayuntamiento"], "e": "Afección real; responsabilidad subsidiaria del adquirente (art. 5.1).", "r": "NF 4/2016 art. 5.1"}, {"id": "abat38q10", "q": "Los ayuntamientos repercuten la cuota del IBI en:", "o": ["Quienes usen mediante contraprestación sus bienes demaniales o patrimoniales", "Todos los vecinos", "La Diputación Foral", "Nadie"], "e": "Están obligados a soportar la repercusión (art. 4.2).", "r": "NF 4/2016 art. 4.2"}, {"id": "abat38q11", "q": "¿Qué grava el IIVTNU (plusvalía municipal)?", "o": ["El incremento de valor de los terrenos de naturaleza urbana que se pone de manifiesto al transmitirse", "El valor de las construcciones", "La titularidad de los inmuebles", "El incremento de valor de los terrenos rústicos"], "e": "Al transmitir la propiedad o constituir o transmitir un derecho real de goce limitativo del dominio.", "r": "NF 8/1989 art. 1"}, {"id": "abat38q12", "q": "El IIVTNU es un impuesto:", "o": ["Directo y potestativo", "Indirecto y obligatorio", "Directo y obligatorio", "Indirecto y potestativo"], "e": "Solo se exige si el ayuntamiento acuerda su imposición y aprueba la ordenanza.", "r": "NF 9/2005 art. 20"}, {"id": "abat38q13", "q": "¿Qué Norma Foral regula el IIVTNU en Bizkaia?", "o": ["La Norma Foral 8/1989, de 30 de junio", "La Norma Foral 4/2016", "La Norma Foral 10/1989", "La Norma Foral 7/1989"], "e": "Muy modificada, entre otras, por el DFN 7/2021 tras la STC 182/2021.", "r": "NF 8/1989"}, {"id": "abat38q14", "q": "El período impositivo del IIVTNU es de hasta:", "o": ["Veinte años", "Diez años", "Cinco años", "Treinta años"], "e": "Tema 38.", "r": "NF 8/1989"}, {"id": "abat38q15", "q": "¿Cuál de estos supuestos NO está sujeto al IIVTNU?", "o": ["La transmisión de un terreno en la que se acredita que no ha habido incremento de valor", "La venta de un piso con ganancia", "La herencia de un solar urbano", "La donación de un terreno urbano"], "e": "Desde 2021, tras la STC 182/2021. El interesado debe declararlo y acreditarlo.", "r": "NF 8/1989 art. 1.4"}, {"id": "abat38q16", "q": "En el IIVTNU, el trato que reciben los cónyuges en las aportaciones a la sociedad conyugal se extiende en Bizkaia a:", "o": ["Las parejas de hecho de la Ley vasca 2/2003", "Los hermanos", "Los socios de una empresa", "Nadie más"], "e": "Particularidad foral.", "r": "NF 8/1989 art. 1.3"}, {"id": "abat38q17", "q": "En una herencia o donación, el contribuyente del IIVTNU es:", "o": ["Quien adquiere el terreno", "Quien transmite el terreno", "El notario", "El ayuntamiento"], "e": "En las transmisiones a título lucrativo.", "r": "NF 8/1989 art. 3"}, {"id": "abat38q18", "q": "En una compraventa, el contribuyente del IIVTNU es:", "o": ["El vendedor (transmitente)", "El comprador (adquirente)", "Los dos a partes iguales", "La inmobiliaria"], "e": "Si el transmitente es una persona física no residente en España, el adquirente es sustituto del contribuyente.", "r": "NF 8/1989 art. 3"}, {"id": "abat38q19", "q": "Los terrenos rústicos a efectos del IBI:", "o": ["No están sujetos al IIVTNU", "Pagan IIVTNU reducido", "Pagan IIVTNU como urbanos", "Solo pagan si se heredan"], "e": "Art. 1.2.", "r": "NF 8/1989 art. 1.2"}]}, {"id": "t39", "sig": "Tema 39", "titulo": "Tema 39. IAE, IVTM e ICIO: naturaleza, hecho imponible y sujeto pasivo", "sub": "Parte Tercera", "preguntas": [{"id": "abat39q01", "q": "¿Cuáles son los impuestos municipales obligatorios en Bizkaia?", "o": ["IBI, IAE e IVTM", "IBI, ICIO e IIVTNU", "IAE, ICIO e IVTM", "IBI, IAE e IIVTNU"], "e": "El ICIO y el IIVTNU son potestativos (art. 20 NF 9/2005).", "r": "NF 9/2005 art. 20"}, {"id": "abat39q02", "q": "¿Cuál es el único impuesto municipal indirecto?", "o": ["El ICIO", "El IBI", "El IAE", "El IVTM"], "e": "Grava el gasto en la obra.", "r": "NF 10/1989"}, {"id": "abat39q03", "q": "El hecho imponible del IAE es:", "o": ["El mero ejercicio de actividades empresariales, profesionales o artísticas, en local determinado o no", "El beneficio obtenido por la empresa", "La titularidad de un local comercial", "La contratación de trabajadores"], "e": "No importa que haya beneficio ni local.", "r": "NF 6/1989 art. 1"}, {"id": "abat39q04", "q": "¿Cuál de estas actividades NO tiene la consideración de actividad empresarial a efectos del IAE?", "o": ["La agricultura", "El comercio", "La minería", "La ganadería independiente"], "e": "Tampoco la ganadería dependiente, la actividad forestal ni la pesca.", "r": "NF 6/1989 art. 1.2"}, {"id": "abat39q05", "q": "¿Cuál de estas actividades NO constituye hecho imponible del IAE?", "o": ["La exposición de artículos con fin exclusivo de decoración del establecimiento", "La venta al por menor habitual", "La prestación de servicios profesionales", "La fabricación de productos"], "e": "También la venta de activo fijo inmovilizado más de 2 años, la de productos recibidos en pago y un solo acto aislado de venta al por menor.", "r": "NF 6/1989 art. 4"}, {"id": "abat39q06", "q": "En Bizkaia, están exentos del IAE los sujetos pasivos con un volumen de operaciones inferior a:", "o": ["2.000.000 de euros", "1.000.000 de euros", "500.000 euros", "3.000.000 de euros"], "e": "En el régimen común, la exención es para cifra de negocios inferior a 1.000.000 € y las personas físicas están siempre exentas.", "r": "NF 6/1989 art. 5.1.h"}, {"id": "abat39q07", "q": "¿Qué Norma Foral regula el IVTM en Bizkaia?", "o": ["La Norma Foral 7/1989, de 30 de junio", "La Norma Foral 6/1989", "La Norma Foral 10/1989", "La Norma Foral 4/2016"], "e": "El IAE es la NF 6/1989; el ICIO, la NF 10/1989.", "r": "NF 7/1989"}, {"id": "abat39q08", "q": "El IVTM grava:", "o": ["La titularidad de los vehículos de tracción mecánica aptos para circular por las vías públicas", "El uso efectivo del vehículo", "La compra del vehículo", "Los kilómetros recorridos"], "e": "Se paga aunque el coche no circule.", "r": "NF 7/1989"}, {"id": "abat39q09", "q": "A efectos del IVTM, un vehículo es apto para circular:", "o": ["Si está matriculado y no ha causado baja en los registros", "Solo si ha pasado la ITV", "Solo si tiene seguro", "Solo si circula habitualmente"], "e": "También los que tienen permisos temporales y matrícula turística.", "r": "NF 7/1989"}, {"id": "abat39q10", "q": "¿Cuál de estos vehículos NO está sujeto al IVTM?", "o": ["Un remolque con carga útil no superior a 750 kg", "Una motocicleta matriculada", "Un camión", "Un turismo de empresa"], "e": "Tampoco los históricos dados de baja que circulan excepcionalmente en exhibiciones.", "r": "NF 7/1989"}, {"id": "abat39q11", "q": "¿Quién es el sujeto pasivo del IVTM?", "o": ["La persona a cuyo nombre conste el vehículo en el permiso de circulación", "El conductor habitual", "La aseguradora", "El último comprador, aunque no haya cambiado la titularidad"], "e": "Se exige por el ayuntamiento del domicilio que consta en el permiso.", "r": "NF 7/1989"}, {"id": "abat39q12", "q": "El hecho imponible del ICIO es la realización de una construcción, instalación u obra que exija licencia, declaración responsable o comunicación previa:", "o": ["Se haya obtenido o no dicha licencia", "Solo si se ha obtenido la licencia", "Solo si la obra supera 6.000 euros", "Solo si la obra es de nueva planta"], "e": "Siempre que su expedición corresponda al ayuntamiento.", "r": "NF 10/1989"}, {"id": "abat39q13", "q": "¿Quién es el contribuyente del ICIO?", "o": ["El dueño de la obra, sea o no propietario del inmueble", "Siempre el propietario del inmueble", "El constructor", "El arquitecto"], "e": "Dueño de la obra: quien soporta su coste.", "r": "NF 10/1989"}, {"id": "abat39q14", "q": "Si la obra no la realiza el contribuyente, son sustitutos en el ICIO:", "o": ["Quienes soliciten las licencias o presenten las declaraciones responsables o comunicaciones previas, o quienes realicen las obras", "Los vecinos colindantes", "El ayuntamiento", "El notario"], "e": "El sustituto puede exigir al contribuyente lo pagado.", "r": "NF 10/1989"}, {"id": "abat39q15", "q": "El ICIO se devenga:", "o": ["Al iniciarse la construcción, instalación u obra, aunque no se haya obtenido la licencia", "Al concederse la licencia", "Al terminar la obra", "El 1 de enero"], "e": "Tema 39.", "r": "NF 10/1989"}, {"id": "abat39q16", "q": "El nombre antiguo del IVTM era:", "o": ["Impuesto sobre Circulación de Vehículos", "Impuesto de Matriculación", "Impuesto de Rodaje", "Tasa de Vehículos"], "e": "El nombre vigente, también en Bizkaia, es IVTM.", "r": "NF 7/1989"}, {"id": "abat39q17", "q": "El IAE es un tributo:", "o": ["Directo, de carácter real y obligatorio", "Indirecto y potestativo", "Directo, personal y potestativo", "Indirecto y obligatorio"], "e": "Art. 1.", "r": "NF 6/1989 art. 1"}, {"id": "abat39q18", "q": "Según el IAE, una actividad se ejerce con carácter empresarial, profesional o artístico cuando supone:", "o": ["La ordenación por cuenta propia de medios de producción y de recursos humanos, o de uno de ambos, para intervenir en la producción o distribución de bienes o servicios", "Trabajar por cuenta ajena", "Tener un local abierto al público", "Obtener beneficios"], "e": "Art. 2.", "r": "NF 6/1989 art. 2"}]}, {"id": "t40", "sig": "Tema 40", "titulo": "Tema 40. Norma Foral presupuestaria de las Entidades Locales de Bizkaia: los presupuestos generales (Título I, Caps. I–IV)", "sub": "Parte Tercera", "preguntas": [], "incluye": ["getxo-administrativo/t38"]}]});
